import {confirmAction,mountMentions} from './interactions.js?v=14.0';
const publicPreview=location.hostname.endsWith('.github.io');
import './theme.js?v=14.0';
import './creation-light.js?v=14.0';
import './atmosphere.js?v=14.0';
import {I,esc,film,referencePage,categories,workflows} from './data.js?v=14.0';
import {logo,replaceLogo} from './brand.js';
import {magneticCTA} from './pointer.js';
import {heroPlayback} from './motion.js';
import {models,defaultModel,getModel,durationOptions,normalizeDraft} from './models.js';
import {openStorage,readAssets,putAsset,deleteAsset,readState,writeState} from './storage.js';
import {createZip,downloadBlob} from './archive.js';
import {advancedValues,advancedCount,advancedFields,cloneDraft,parameterRows} from './advanced.js';

let liveCatalog=[];
try{const response=publicPreview?null:await fetch('/api/workflows');if(response?.ok)liveCatalog=await response.json();}catch{}
if(liveCatalog.length){workflows.splice(0,workflows.length,...liveCatalog.map(w=>({...w,live:true,category:w.category==='video-gen'?'视频生成':'视频编辑',cover:w.cover.replace('assets/',''),tag:'已接入',input:w.id==='h3-reference'?'文字 · 参考图片':'原视频 · 可选参考图片'})));categories.splice(0,categories.length,'全部','视频生成','视频编辑');}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const main=$('#main'),shell=$('#shell'),dialog=$('#dialog');
const production=location.pathname.endsWith('studio.html');
document.body.insertAdjacentHTML('beforeend','<div id="floating-panel" class="floating-panel glass" hidden></div>');
const panel=$('#floating-panel');
const DEMO_DURATION=12000;
const images=['assets/coast.jpg','assets/mountain.jpg','assets/forest.jpg','assets/dunes.jpg','assets/portal-ocean.png'];
let nextSession=1,nextJob=1,refSequence={image:0,video:0,audio:0},toastTimer,cleanup=[],resizeObserver,panelAnchor,panelPoint;
const state={sessions:[],active:null,query:'',category:'全部',selected:new Set(),filter:'全部',failNext:new URLSearchParams(location.search).get('demo')==='fail-once'};
function newDraft(type='image'){return{type,prompt:'',refs:[],model:defaultModel(type).id,mode:'全能参考',ratio:'16:9',quality:type==='image'?'2K':'1080p',duration:'10 秒',count:2,negative:'',advanced:{},error:null};}
function makeSession(scope='model',type='image'){const s={id:'s'+nextSession++,scope,title:'新的创作',draft:newDraft(type),jobs:[]};state.sessions.push(s);state.active=s.id;return s;}
makeSession();
const active=()=>state.sessions.find(s=>s.id===state.active)||state.sessions[0];
function route(){let h='';try{h=decodeURIComponent(location.hash.slice(1));}catch{}const [name,id]=h.split('/');return{name:name||'create',id};}
const workflow=s=>s.scope.startsWith('wf:')?workflows.find(w=>w.id===s.scope.slice(3)):null;
function resolveSession(){const r=route();if(r.name==='new'){const s=makeSession();history.replaceState(null,'','#session/'+s.id);}if(r.name==='session'){const s=state.sessions.find(s=>s.id===r.id);if(s)state.active=s.id;}
 if(r.name==='workflow'){const w=workflows.find(w=>w.id===r.id)||workflows[0];let s=state.sessions.findLast(s=>s.scope==='wf:'+w.id);if(!s)s=makeSession('wf:'+w.id,w.category.startsWith('视频')?'video':'image');state.active=s.id;if(w.mode==='pair')s.draft.mode='首尾帧';}
 if(['create','image','video'].includes(r.name)){if(active().scope!=='model'){const s=state.sessions.findLast(s=>s.scope==='model')||makeSession();state.active=s.id;}if(r.name==='image'||r.name==='video'){const d=active().draft;d.type=r.name;d.model=defaultModel(d.type).id;d.quality=r.name==='video'?'1080p':'2K';history.replaceState(null,'','#create');}}
 return active();
}
const B=(text,action,cls='small-button',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function cost(d){const base=d.type==='video'?(parseInt(d.duration)*4):4*Number(d.count);const quality=d.quality==='4K'?2:d.quality==='720p'||d.quality==='1K'?.5:1;const model=getModel(d).factor;return Math.ceil(base*quality*model);}
function visibleRefs(d=active().draft){return d.mode==='纯文本'?[]:d.refs.filter(r=>(d.type!=='image'||r.kind==='image')&&(d.mode==='首尾帧'?r.slot!==undefined:r.slot===undefined));}
function formatTime(ms){const n=Math.floor(ms/1000);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function brandLink(){return `<a class="brand ${production?'':'brand-reveal'}" href="index.html" aria-label="映序首页">${logo()}<span class="brand-name">映序<small>YINGXU</small></span></a>`;}
function landing(){document.body.className='landing';shell.innerHTML='';
 main.innerHTML=`<section class="landing-masthead"><div class="masthead-top">${brandLink()}<a class="masthead-link control" href="studio.html#library">我的作品 ${I('arrow')}</a></div><div class="masthead-body"><h1>把想象，<br><span>变成下一帧</span><i aria-hidden="true"></i></h1><div class="masthead-aside"><p>图像、视频与工作流。<br>让每一个想法，都有自己的画面。</p><a class="button primary" href="studio.html#workflows">进入工作台 ${I('arrow')}</a></div></div></section><section class="film-stage" id="film-stage" aria-label="获奖 AI 短片十秒节选"><video id="hero-video" src="${film.src}" poster="${film.poster}" muted loop playsinline preload="auto" aria-label="Love at First Sight 十秒节选"></video><a class="film-hit" href="studio.html#workflows" tabindex="-1" aria-hidden="true"></a><div class="film-topline"><span class="glass">精选影像 / 01</span><span class="glass">10 SEC / EXCERPT</span></div><a class="magnetic-cta" id="magnetic-cta" href="studio.html#workflows">开始制作 ${I('arrow')}</a><div class="film-bottom"><div><h2>${film.title}</h2><p>${film.author} · ${film.award}</p></div><div class="film-actions"><button id="film-pause">暂停片段</button><a class="control" href="${referencePage}" target="_blank" rel="noreferrer">作品来源 ↗</a></div></div></section>${landingExtension()}<footer class="landing-footer"><span>映序 YINGXU · 从你的想象出发</span><a href="studio.html#assets">把素材留给下一次灵感 ${I('arrow')}</a></footer>`;
 cleanup.push(magneticCTA($('#film-stage'),$('#magnetic-cta')),heroPlayback($('#hero-video'),$('#film-pause')));
}

function sidebar(){const r=route(),wf=workflow(active());const creating=!['workflows','library','assets','settings'].includes(r.name);shell.innerHTML=`<aside class="sidebar glass" aria-label="主导航">${brandLink()}${B(I('plus')+'新建创作','new','button new-session')}<nav>${[['create','模型预览','spark',creating&&!wf],['workflows','工作流','grid',r.name==='workflows'||creating&&wf],['library','我的作品','assets',r.name==='library'],['assets','素材库','folder',r.name==='assets']].map(([id,t,i,on])=>`<a class="nav-item ${on?'active':''}" href="#${id}" ${on?'aria-current="page"':''}>${I(i)}${t}</a>`).join('')}</nav><div class="session-nav">${state.sessions.some(s=>s.jobs.length)?'<p>最近创作</p>':''}${state.sessions.filter(s=>s.jobs.length).slice(-7).reverse().map(s=>`<a href="#session/${s.id}" class="session-link ${creating&&s.id===state.active?'active':''}" title="${esc(s.title)}">${I(s.draft.type==='video'?'video':'image')}<span>${esc(s.title)}</span></a>`).join('')}</div><div class="sidebar-end"><a class="nav-item ${r.name==='settings'?'active':''}" href="#settings">${I('settings')}偏好设置</a></div></aside><button class="mobile-menu icon-button" data-action="menu" aria-label="打开导航">${I('menu')}</button><div class="nav-curtain" data-action="close-nav"></div>`;}
function refsMarkup(d){if(d.mode==='首尾帧')return `<div class="reference-strip pair-strip">${[0,1].map(slot=>{const ref=d.refs.find(r=>r.slot===slot);return `<div class="pair-cell">${ref?`<img src="${esc(ref.src)}" alt="${slot===0?'首帧':'尾帧'}"><span>${slot===0?'首帧':'尾帧'}</span><button class="remove-ref" data-remove="${ref.id}" aria-label="移除${slot===0?'首帧':'尾帧'}">${I('close')}</button>`:uploadControl(d,true,slot)}</div>`;}).join('')}<span class="ref-note">从首帧出发，过渡到尾帧。</span></div>`;
 const refs=visibleRefs(d);if(!refs.length)return'';return `<div class="reference-strip">${refs.map(r=>`<div class="ref-tile"><button data-mention="${r.id}" aria-label="引用${r.id}" title="${esc(r.name)}">${r.kind==='image'?`<img src="${esc(r.src)}" alt="">`:r.kind==='video'?`<video src="${esc(r.src)}" ${r.poster?`poster="${r.poster}"`:""} preload="metadata" muted></video>`:I('audio')}<span>@${r.id}</span></button><button class="remove-ref" data-remove="${r.id}" aria-label="移除${r.id}">${I('close')}</button></div>`).join('')}${uploadControl(d,true)}<span class="ref-note">${refs.length}/${referenceLimit(d)} · 点击引用</span></div>`;
}
function issueHTML(d){if(!d.error)return'';return `<div class="inline-error" role="alert"><span>${I('help')} ${esc(d.error.text)}</span><div>${d.error.fix==='example'?B('填入示例','example'):d.error.fix==='refs'?B('移除失效引用','fix-refs'):d.error.fix==='refs-library'?B('选择兼容素材','open-assets'):d.error.fix==='capacity'?B('移除最后一份素材','trim-ref'):B('重新选择素材','upload')}${B('关闭','dismiss-error')}</div></div>`;}
function placeholder(d){if(workflow(active())?.mode==='video')return'上传原视频，可补充希望改善的细节。';return d.type==='video'?'描述主体怎么动、镜头怎么走；上传素材后点击缩略图 @引用。':'描述主体、场景和风格；可上传参考图，再用 @ 指定它的作用。';}
function composer(){if(liveWorkflow())return liveComposer(active(),liveWorkflow());const s=active(),d=normalizeDraft(s.draft),w=workflow(s),refs=visibleRefs(d),hasJobs=s.jobs.length;return `<section class="composer glass" aria-label="创作操作区">${w?`<div class="workflow-strip"><a class="control small-button" href="#workflows">${I('back')}工作流</a><span>${w.name}</span></div>`:''}${refsMarkup(d)}<div class="writing-row"><div class="writing-area"><label for="prompt" class="sr-only">${d.type==='video'?'镜头描述':'画面描述'}</label><textarea id="prompt" spellcheck="false" maxlength="6000" placeholder="${placeholder(d)}" rows="${hasJobs?3:5}">${esc(d.prompt)}</textarea></div><button class="expand-writing icon-button" data-action="expand" aria-label="展开描述编辑区" title="展开编辑">${I('expand')}</button></div>${issueHTML(d)}<div class="composer-controls"><div class="control-cluster">${!refs.length&&d.mode!=='首尾帧'&&d.mode!=='纯文本'?uploadControl(d):''}${!w?`<button class="intent-control" data-popup="type">${I(d.type)}${d.type==='video'?'视频生成':'图像生成'}${I('down')}</button><button class="intent-control model-control" data-popup="model">${I('spark')}${getModel(d).name}${I('down')}</button>`:''}${d.type==='video'&&!w?`<button class="intent-control" data-popup="reference">${d.mode}${I('down')}</button>`:''}<button class="intent-control" data-popup="picture" aria-label="${d.type==='image'?'比例、分辨率与数量':'画面设置'}">${d.ratio} · ${d.quality}${d.type==='image'?' · '+d.count+' 张':''}${I('down')}</button>${d.type==='video'?`<button class="intent-control duration-control" data-popup="output" aria-label="视频时长">${I('clock')}${d.duration}</button>`:''}<button class="intent-control extra-control" data-popup="more" aria-label="高级设置">${I('settings')}<span>高级</span><i class="settings-count" ${advancedCount(d,w)?'':'hidden'}>${advancedCount(d,w)}</i></button>${refs.length?B('@','mention','intent-control mention-control','aria-label="引用素材"'):''}</div><button class="button primary generate" data-action="generate">${I('spark')}演示生成 · 不扣费 ${I('arrow')}</button></div></section><div class="composer-foot"><span>${!hasJobs?B('填入一段示例','example','text-control'):''}</span><span>演示费率 · 不扣费<span class="keyboard-hint"> · Ctrl / ⌘ + Enter</span></span></div><div class="composer-utilities">${B(I('folder')+'素材库','open-assets','text-control')}${B(I('checklist')+'批量提示词','batch-prompts','text-control')}</div>`;}
function outputHTML(o,job,idx){const selected=route().name==='library'?workspace.workSelected.has(o.id):state.selected.has(o.id);return `<article class="output ${selected?'selected':''}" data-output="${o.id}" tabindex="0" aria-label="${o.type==='video'?'视频':'图像'}结果 ${idx+1}，按菜单键可打开处理选项"><button class="media-open" data-view="${o.id}" aria-label="查看结果 ${idx+1}">${o.type==='video'?`<video src="${o.src}" ${o.poster?`poster="${o.poster}"`:''} preload="metadata" muted playsinline></video><span class="video-play">${I('play')}</span>`:`<img src="${o.src}" alt="演示图像结果 ${idx+1}" loading="lazy">`}</button><span class="output-index">${String(idx+1).padStart(2,'0')}${o.type==='video'?(job.real?' · 视频':' · 00:10'):''}</span><button class="select-output ${selected?'active':''}" data-select="${o.id}" aria-label="${route().name==='library'?(selected?'取消选择':'选择'):(selected?'取消对比':'加入对比')}结果 ${idx+1}" aria-pressed="${selected}">${I(selected?'check':'plus')}<span>${route().name==='library'?'选择':'对比'}</span></button><button class="output-menu icon-button" data-context="${o.id}" aria-label="结果 ${idx+1} 的处理选项">···</button></article>`;}
function jobMeta(j){const d=j.snapshot;if(j.real){const v=d.liveSettings||{};return `${esc(workflows.find(w=>w.id===d.workflowId)?.name||'工作流')} <span>·</span> ${v.ratio||'跟随原片'} <span>·</span> ${v.megapixels?qualityName(v.megapixels):v.long_side+' px'} <span>·</span> ${v.duration} 秒`;}return `${d.workflowId?(workflows.find(w=>w.id===d.workflowId)?.name||'工作流'):((d.type==='video'?'视频':'图像')+' · '+getModel(d).name)} <span>·</span> ${d.ratio} <span>·</span> ${d.quality} <span>·</span> ${d.type==='video'?d.duration:d.count+' 张'} <span>·</span> ${j.cost} 演示积分`;}
function statusInfo(j){const t=Math.max(0,(j.ended||Date.now())-j.started);let phase=t<2200?0:t<9500?1:2;return{elapsed:t,phase,names:['准备参考素材',j.snapshot.type==='video'?'生成镜头':'生成画面','整理生成结果']};}
function progressHTML(j){if(j.real)return liveJobStatus(j);const{elapsed,phase,names}=statusInfo(j);if(j.status==='failed')return `<div class="task-failure"><div>${I('help')}<strong>${j.reason==='interrupted'?'页面已刷新，演示任务中断':'模拟超时：这次生成暂未完成'}</strong></div><p>描述和素材已保留。可以直接重试，或修改后重新生成；本地演示不扣费。</p><div>${B('重试 · '+j.cost+' 积分','retry','small-button primary',`data-job="${j.id}"`)}${B('修改描述','reedit','small-button',`data-job="${j.id}"`)}</div></div>`;
 if(j.status==='cancelled')return `<div class="cancelled-task"><span>已取消 · 等待 ${formatTime(elapsed)}</span>${B('重新生成 · '+j.cost+' 积分','retry','small-button',`data-job="${j.id}"`)}</div>`;
 return `<div class="task-progress"><div class="progress-line"><span class="live-dot"></span><strong>${names[phase]}</strong><span class="elapsed">已等待 <time>${formatTime(elapsed)}</time></span>${B('取消','cancel','small-button',`data-job="${j.id}"`)}</div><div class="progress-track"><span style="width:${Math.min(97,elapsed/DEMO_DURATION*100)}%"></span></div><div class="progress-steps">${names.map((n,i)=>`<span class="${i===phase?'current':i<phase?'done':''}">${i<phase?'✓':String(i+1).padStart(2,'0')} ${n}</span>`).join('')}</div><p>本地演示生成流程 · 完成后在本栏显示结果</p></div>`;
}
function jobHTML(j,index){return `<article class="job-row" id="job-${j.id}" data-job-id="${j.id}"><div class="job-top"><span class="job-order">${String(index+1).padStart(2,'0')}</span><div class="job-prompt"><p>${esc(j.snapshot.prompt||'使用参考素材进行创作')}</p>${j.snapshot.prompt.length>130?B('展开描述','full-prompt','text-control',`data-job="${j.id}"`):''}<div class="job-meta">${jobMeta(j)} ${B('参数','job-settings','text-control',`data-job="${j.id}"`)} <span class="demo-mark">${j.real?'真实生成':j.status==='done'?'演示结果':'演示任务'}</span></div></div></div><div class="job-body">${j.status==='done'?`<div class="output-grid count-${j.outputs.length}">${j.outputs.map((o,i)=>outputHTML(o,j,i)).join('')}</div>`:progressHTML(j)}</div><div class="job-actions">${j.status==='done'?`${B(I('expand')+'重新编辑','reedit','small-button',`data-job="${j.id}"`)}${B(I('history')+(j.real?'再次生成 · 算力卡计费':'再次生成 · '+j.cost+' 积分'),'rerun','small-button',`data-job="${j.id}"`)}${j.outputs.length>1?B('并排对比','batch-compare','small-button',`data-job="${j.id}"`):''}<span>完成用时 ${formatTime((j.ended||Date.now())-j.started)}</span>`:''}</div></article>`;}
function feedHTML(s){return s.jobs.map(jobHTML).join('');}
function refreshFeed(scroll=false){const feed=$('#result-feed');if(!feed)return;const nearEnd=feed.scrollHeight-feed.scrollTop-feed.clientHeight<100;feed.querySelector('.result-stream').innerHTML=feedHTML(active());syncSelection();if(scroll||nearEnd)feed.scrollTop=feed.scrollHeight;}
function refreshComposer(){const holder=$('#composer-slot');if(!holder)return;const old=$('#prompt'),focused=old===document.activeElement,start=old?.selectionStart,end=old?.selectionEnd;holder.innerHTML=composer();if(focused){$('#prompt').focus();$('#prompt').setSelectionRange(start,end);}observeComposer();}
let clearMentions=()=>{};
function observeComposer(){clearMentions();clearMentions=mountMentions($('#prompt'),()=>visibleRefs());resizeObserver?.disconnect();const holder=$('#composer-slot');if(holder){resizeObserver=new ResizeObserver(()=>document.documentElement.style.setProperty('--dock-height',holder.offsetHeight+'px'));resizeObserver.observe(holder);}}
function compactDescription(w){return ({'h3-reference':'参考图生成有声视频，最多 9 张图。','bernini-edit':'修改人物或场景，保留原片动作与声音。'})[w.id]||w.desc?.slice(0,46)||'';}
function workflowCard(w){return `<a class="workflow-card" href="#workflow/${w.id}" aria-describedby="description-${w.id}"><div class="workflow-cover"><img src="assets/${w.cover}" alt="" loading="lazy"></div><div class="workflow-info"><h2>${esc(w.name)}</h2><p id="description-${w.id}">${esc(compactDescription(w))}</p></div></a>`;}
function gallery(){const list=workflows.filter(w=>(state.category==='全部'||w.category===state.category)&&(!state.query||(w.name+w.desc+w.category).includes(state.query)));return `<section class="library-page workflow-page"><header class="library-head compact-head"><h1>工作流</h1><div class="category-tabs" aria-label="工作流分类">${categories.map(c=>`<button class="category ${c===state.category?'active':''}" data-category="${c}" aria-pressed="${c===state.category}">${c}</button>`).join('')}</div><label class="searchbox">${I('search')}<input id="workflow-search" aria-label="搜索工作流" placeholder="搜索工作流" value="${esc(state.query)}"></label></header><div class="workflow-grid">${list.map(workflowCard).join('')||`<div class="useful-empty"><h2>没有匹配的工作流</h2><p>试试“视频生成”或“视频编辑”。</p>${B('清除筛选','reset-search','button')}</div>`}</div></section>`;}

function findOutput(id){for(const s of state.sessions)for(const j of s.jobs){const o=j.outputs.find(o=>o.id===id);if(o)return{o,j,s};}return null;}
function findJob(id){for(const s of state.sessions){const j=s.jobs.find(j=>j.id===id);if(j)return{j,s};}return null;}
function allOutputs(){return state.sessions.flatMap(s=>s.jobs.flatMap(j=>j.outputs.map(o=>({o,j,s}))));}
function settings(){return `<section class="library-page settings-page"><header class="library-head"><h1>偏好设置</h1></header><div class="settings-panel glass"><h2>品牌标志</h2><p>替换 Logo，不改变首页影片或鼠标跟随效果。</p><div class="logo-lab">${logo()}<div>${B('流线标志','logo-original')}${B('宽字标','logo-wide')}${B('纯文字','logo-text')}<label class="brand-upload control small-button">上传 Logo<input type="file" id="logo-upload" accept="image/svg+xml,image/png,image/webp,image/jpeg" aria-label="上传 Logo"></label></div></div></div><div class="settings-panel glass"><h2>动态效果</h2><p>跟随系统的“减少动态效果”设置；触屏设备的首页按钮固定居中。</p><a class="control small-button" href="index.html">查看首页 ${I('arrow')}</a></div></section>`;}
function render(){closePanel();dialog.close();cleanup.forEach(f=>f());cleanup=[];document.body.classList.remove('nav-open');if(!production){landing();return;}resolveSession();document.body.className='production';sidebar();const r=route();main.innerHTML=r.name==='workflows'?gallery():r.name==='library'?library():r.name==='assets'?assetLibrary():r.name==='settings'?settings():creation();document.title=(r.name==='workflows'?'工作流':r.name==='library'?'我的作品':r.name==='assets'?'素材库':r.name==='settings'?'偏好设置':'创作')+' · 映序';observeComposer();if(route().name==='library')syncWorkSelection();else syncSelection();if($('#result-feed'))$('#result-feed').scrollTop=$('#result-feed').scrollHeight;}
function closePanel(restoreFocus=false){if(restoreFocus&&panelAnchor?.isConnected)panelAnchor.focus({preventScroll:true});panel.hidden=true;panel.innerHTML='';$$('[aria-expanded="true"]').forEach(b=>b.setAttribute('aria-expanded','false'));}
function positionPanel(anchor,point){panel.style.left='0';panel.style.top='0';const r=anchor?.getBoundingClientRect(),x=point?.x??r.left,y=point?.y??r.bottom+8;const width=panel.offsetWidth,height=panel.offsetHeight;panel.style.left=Math.max(12,Math.min(innerWidth-width-12,x))+'px';panel.style.top=Math.max(12,y+height>innerHeight-12?(point?.y??r.top)-height-8:y)+'px';}
function popup(anchor,title,html,point){panel.classList.remove('compact-options','duration-popup','advanced-popup','picture-popup');panelAnchor=anchor;panelPoint=point;panel.innerHTML=`<div class="panel-title"><strong>${title}</strong>${B(I('close'),'close-panel','icon-button','aria-label="关闭菜单"')}</div>${html}`;panel.hidden=false;anchor?.setAttribute('aria-expanded','true');positionPanel(anchor,point);panel.querySelector('[data-param],.context-option,[data-advanced],#negative,[data-mention]')?.focus({preventScroll:true});}
new ResizeObserver(()=>{if(!panel.hidden)positionPanel(panelAnchor,panelPoint);}).observe(panel);
function options(key,items,current){return `<div class="option-list">${items.map(([value,detail])=>`<button data-param="${key}" data-value="${value}" class="${String(current)===String(value)?'chosen':''}" aria-pressed="${String(current)===String(value)}"><span>${value}${detail?`<small>${detail}</small>`:''}</span>${String(current)===String(value)?I('check'):''}</button>`).join('')}</div>`;}
function example(){const d=active().draft;if(liveWorkflow()){d.prompt=liveWorkflow().id==='h3-reference'?'清晨的海岸，海浪缓缓拍打礁石，镜头平稳向前推进，柔和自然光，伴随海浪声。':'将天空和光线改为温暖的金色日落，保留海浪的运动、原有构图与镜头移动。';d.error=null;refreshComposer();scheduleSave();return;}d.prompt=d.type==='video'?'黄昏的摩天轮缓缓转动，镜头沿座舱平稳上升。远处城镇的灯光依次亮起，保持自然的动作与柔和的电影光线。':'一组安静的自然景观，海岸、山谷与森林。清晨柔和的光线，真实的纹理，低饱和色彩，电影摄影感。';d.error=null;refreshComposer();$('#prompt')?.focus();}
function inlineError(text,fix='upload'){active().draft.error={text,fix};refreshComposer();}
function addRefFromOutput(o,d=active().draft){if(visibleRefs(d).length>=referenceLimit(d)){inlineError('当前模型最多使用 '+referenceLimit(d)+' 份参考，请先移除不需要的素材。','capacity');return false;}const prefix=o.type==='video'?'视频':'图片';d.refs.push({id:prefix+(++refSequence[o.type]),kind:o.type,name:'结果参考',src:o.src,poster:o.poster});d.error=null;return true;}
function insertMention(id){const p=$('#prompt');if(!p)return;p.setRangeText('@'+id+' ',p.selectionStart,p.selectionEnd,'end');active().draft.prompt=p.value;p.dispatchEvent(new Event('mentionchange'));p.focus();scheduleSave();}
function submit(snapshot,session=active(),retryJob){if(liveWorkflow(session))return submitLive(snapshot,session,retryJob);const d=cloneDraft(snapshot||session.draft);normalizeDraft(d);d.workflowId=workflow(session)?.id||null;d.advanced=advancedValues(d,workflow(session));d.parameterSchemaVersion=1;const incompatibility=referenceProblem(d,session);if(incompatibility){inlineError(incompatibility,'refs-library');return false;}if(!d.prompt.trim()&&!visibleRefs(d).length){inlineError('先写一句画面描述，或添加参考素材。可以从示例开始。','example');$('#prompt')?.focus();return;}if(d.mode==='首尾帧'&&(!d.refs.some(r=>r.slot===0)||!d.refs.some(r=>r.slot===1))){inlineError('首尾帧需要起点和终点两张图片，请补齐缺少的图片。');return;}const tokens=d.prompt.match(/@(图片|视频|音频)\d+/g)||[],ids=visibleRefs(d).map(r=>'@'+r.id),missing=tokens.filter(t=>!ids.includes(t));if(missing.length){inlineError(`${[...new Set(missing)].join('、')}没有对应素材。重新添加素材，或移除这些引用。`,'refs');return;}
 const started=Date.now(),j=retryJob||{id:'j'+nextJob++,outputs:[]};Object.assign(j,{snapshot:d,cost:cost(d),started,ended:null,status:'running',reason:null,outputs:[],fail:state.failNext});state.failNext=false;if(!retryJob)session.jobs.push(j);session.title=d.prompt.slice(0,28)||workflow(session)?.name||'参考素材创作';session.draft.error=null;state.active=session.id;
 if(!$('#result-feed'))render();else{sidebar();refreshFeed(true);}refreshComposer();closePanel();scheduleSave();return true;}
function complete(j){j.status='done';j.ended=j.started+DEMO_DURATION;const count=j.snapshot.type==='video'?1:Number(j.snapshot.count);const jobNumber=Number(j.id.slice(1));j.outputs=Array.from({length:count},(_,i)=>({id:j.id+'o'+i,type:j.snapshot.type,src:j.snapshot.type==='video'?film.src:images[((jobNumber-1)*2+i)%images.length],poster:j.snapshot.type==='video'?film.poster:null}));}
function tickJobs(){let completed=false;for(const s of state.sessions)for(const j of s.jobs){if(j.status!=='running')continue;if(j.real){const t=$('#job-'+j.id+' time');if(t)t.textContent=formatTime(Date.now()-j.started);continue;}const elapsed=Date.now()-j.started;if(j.fail&&elapsed>=6000){j.status='failed';j.ended=Date.now();completed=true;}else if(elapsed>=DEMO_DURATION){complete(j);completed=true;}const root=$('#job-'+j.id+' .job-body');if(root&&j.status==='running'){const info=statusInfo(j);root.querySelector('.progress-line strong').textContent=info.names[info.phase];root.querySelector('time').textContent=formatTime(info.elapsed);root.querySelector('.progress-track>span').style.width=Math.min(97,info.elapsed/DEMO_DURATION*100)+'%';root.querySelectorAll('.progress-steps>span').forEach((step,i)=>{step.className=i===info.phase?'current':i<info.phase?'done':'';step.textContent=(i<info.phase?'✓':String(i+1).padStart(2,'0'))+' '+info.names[i];});}}if(completed){scheduleSave();if($('#result-feed'))refreshFeed();else if(route().name==='library'&&!dialog.open)render();sidebar();}}
function syncSelection(){const valid=allOutputs().map(({o})=>o.id);for(const id of state.selected)if(!valid.includes(id))state.selected.delete(id);$$('[data-output]').forEach(el=>{const on=state.selected.has(el.dataset.output);el.classList.toggle('selected',on);const b=el.querySelector('[data-select]');b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);b.innerHTML=I(on?'check':'plus')+'<span>对比</span>';});const tray=$('#compare-tray');if(tray){tray.hidden=!state.selected.size;tray.innerHTML=`<span>已选 ${state.selected.size} 项</span>${B('并排对比','compare','small-button primary',state.selected.size<2?'disabled':'')}${B('清空','clear-compare','small-button')}`;}}
function selectOutput(id){if(state.selected.has(id))state.selected.delete(id);else{if(state.selected.size>=4){toast('一次最多比较 4 个结果。先取消一个，再加入新的。');return;}const first=findOutput([...state.selected][0])?.o,o=findOutput(id)?.o;if(first&&first.type!==o.type){toast('请比较同一类型的结果。先清空选择，再选择图像或视频。');return;}state.selected.add(id);}syncSelection();}
function modal(title,html,cls=''){closePanel();dialog.className=cls;dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${B(I('close'),'close-dialog','icon-button','aria-label="关闭弹窗"')}</div>${html}`;dialog.showModal();}
function viewOutput(id){const found=findOutput(id);if(!found)return;const{o,j}=found;modal('查看结果',`<div class="viewer-media">${o.type==='video'?`<video src="${o.src}" ${o.poster?`poster="${o.poster}"`:''} controls autoplay muted playsinline></video>`:`<img src="${o.src}" alt="图像结果">`}</div><div class="viewer-actions">${B('用作参考','reference','small-button',`data-id="${id}"`)}${B('继续编辑','edit-result','small-button',`data-id="${id}"`)}<a class="small-button control" href="${o.src}" download>下载文件</a></div><p class="viewer-meta">${jobMeta(j)} · ${j.real?"已保存到本地":"本地演示素材"}</p>`,'viewer-dialog');}
function contextMenu(id,anchor,point){const o=findOutput(id)?.o;if(!o)return;popup(anchor,'处理这个结果',`<div class="context-options">${[['放大查看','view'],['用作参考','reference'],['保存到素材库','save-output'],['继续编辑','edit-result'],...(o.type==='image'?[['生成视频','to-video']]:[]),['加入 / 取消对比','select-result']].map(([t,a])=>B(t,a,'context-option',`data-id="${id}"`)).join('')}<a class="context-option control" href="${o.src}" download>下载文件 ${I('down')}</a></div>`,point);}
function compare(){const items=[...state.selected].map(findOutput).filter(Boolean);if(items.length<2)return;const video=items[0].o.type==='video';modal('并排比较',`<div class="compare-tools"><span>${items.length} 个结果 · 相同显示尺寸</span>${video?B('同步播放 / 暂停','sync-video','small-button'):B('放大细节','compare-zoom','small-button')}</div><div class="compare-grid" style="--compare-count:${items.length}">${items.map(({o,j},i)=>`<figure><div class="compare-media">${video?`<video src="${o.src}" ${o.poster?`poster="${o.poster}"`:''} muted playsinline controls></video>`:`<img src="${o.src}" alt="对比结果 ${i+1}">`}</div><figcaption><strong>结果 ${i+1}</strong><span>${j.snapshot.quality} · ${j.snapshot.ratio}</span></figcaption><p>${esc(j.snapshot.prompt)}</p>${B('用作参考','reference','small-button',`data-id="${o.id}"`)}</figure>`).join('')}</div>`,'compare-dialog');}
function openOutputTask(id,action){const found=findOutput(id);if(!found)return;const{o}=found;if(action==='reference'){const d=active().draft;if(liveWorkflow()&&o.type==='video'&&!liveWorkflow().maxVideos){toast('此工作流只接收图片，请使用“继续编辑”进入视频编辑。');return;}if(d.type==='image'&&o.type==='video'){toast('视频参考需要视频生成模式，请使用“继续编辑”。');return;}d.mode='全能参考';if(addRefFromOutput(o,d)){dialog.close();closePanel();location.hash='session/'+active().id;render();$('#prompt')?.focus();toast('已加入参考素材，继续描述希望如何使用它。');}return;}
 const type='video',scope='wf:'+(o.type==='video'?'bernini-edit':'h3-reference');
 const s=makeSession(scope,type);addRefFromOutput(o,s.draft);s.draft.prompt='';dialog.close();location.hash='session/'+s.id;render();$('#prompt')?.focus();}
async function reedit(id){const found=findJob(id);if(!found)return;const{s,j}=found;if(j.real&&j.remoteId){try{mergeLiveJob(j,await liveApi('/api/jobs/'+j.remoteId));}catch(e){toast(e.message);return;}}state.active=s.id;s.draft={...cloneDraft(j.snapshot),error:null};location.hash='session/'+s.id;render();await saveWorkspace();$('#prompt')?.focus();}
function handleAction(a,el,confirmed=false){if(!confirmed&&['delete-assets','delete-collection','trim-ref'].includes(a)){const message=a==='delete-assets'?`将从素材库删除所选 ${workspace.assetSelected.size} 份素材。删除后无法撤销，正在使用的素材会保留。`:a==='delete-collection'?'删除这个分类后，作品会保留在「未分类」中。':'从本次创作移除这份参考素材，素材库中的原文件仍会保留。';confirmAction({title:a==='delete-collection'?'删除分类？':a==='trim-ref'?'移除参考素材？':'删除所选素材？',message}).then(ok=>{if(ok)handleAction(a,el,true);});return;}if(handleWorkspaceAction(a,el))return;switch(a){case'job-settings':showJobSettings(el.dataset.job);break;case'reset-advanced':{active().draft.advanced={};active().draft.negative='';openIntent($('[data-popup="more"]'));updateAdvancedBadge();scheduleSave();break;}case'menu':document.body.classList.add('nav-open');break;case'close-nav':document.body.classList.remove('nav-open');break;case'new':{const r=route(),old=active();const s=makeSession(['workflows','library','assets','settings'].includes(r.name)?'model':old.scope,old.draft.type);location.hash='session/'+s.id;render();break;}case'example':example();break;case'generate':submit();break;case'upload':openAssetPicker();break;case'trim-ref':{const d=active().draft,r=visibleRefs(d).at(-1);if(r){d.refs=d.refs.filter(x=>x.id!==r.id);d.error=d.prompt.includes('@'+r.id)?{text:'素材已移除，请同时移除描述中的失效引用。',fix:'refs'}:null;refreshComposer();}break;}case'dismiss-error':active().draft.error=null;refreshComposer();break;case'fix-refs':{const d=active().draft,ids=visibleRefs(d).map(r=>'@'+r.id);d.prompt=d.prompt.replace(/@(图片|视频|音频)\d+/g,t=>ids.includes(t)?t:'');d.error=null;refreshComposer();break;}case'expand':{const open=$('.composer-slot').classList.toggle('expanded-writing');el.setAttribute('aria-label',open?'收起描述编辑区':'展开描述编辑区');el.title=open?'收起编辑':'展开编辑';$('#prompt')?.focus();break;}case'close-panel':if(liveWorkflow()&&panel.querySelector('input:invalid')){panel.querySelector('input:invalid').reportValidity();return;}closePanel(true);break;case'close-dialog':dialog.close();break;case'mention':popup(el,'引用素材',`<div class="context-options">${visibleRefs().map(r=>`<button class="context-option" data-mention="${r.id}">@${r.id}<small>${esc(r.name)}</small></button>`).join('')}</div>`);break;case'cancel':{const j=findJob(el.dataset.job)?.j;if(j)confirmAction({title:'取消这次生成？',message:j.real?'任务可能已经使用算力并产生费用，取消不会退回已发生的费用；算力卡运行费用也不会因此停止。提示词和素材会保留。':'这是不扣费的演示任务。取消后，提示词和素材仍会保留。',label:'取消任务'}).then(ok=>{if(!ok||j.status!=='running')return;if(j.real)cancelLive(j);else{j.status='cancelled';j.ended=Date.now();refreshFeed();scheduleSave();}});break;}case'retry':{const found=findJob(el.dataset.job);if(found){if(found.j.real&&found.j.remoteId)rerunLive(found.j,found.s,el);else submit(found.j.snapshot,found.s,found.j);}break;}case'rerun':{const found=findJob(el.dataset.job);if(found){if(found.j.real)rerunLive(found.j,found.s,el);else submit(found.j.snapshot,found.s);}break;}case'reedit':if(dialog.open)dialog.close();reedit(el.dataset.job);break;case'full-prompt':el.closest('.job-prompt').classList.toggle('show-full');el.textContent=el.closest('.job-prompt').classList.contains('show-full')?'收起描述':'展开描述';break;case'batch-compare':{const j=findJob(el.dataset.job)?.j;if(j){state.selected=new Set(j.outputs.slice(0,4).map(o=>o.id));syncSelection();compare();}break;}case'compare':compare();break;case'clear-compare':state.selected.clear();syncSelection();break;case'select-result':if(route().name==='library')toggleWork(el.dataset.id);else selectOutput(el.dataset.id);closePanel();break;case'view':viewOutput(el.dataset.id);break;case'reference':case'edit-result':case'to-video':case'upscale':openOutputTask(el.dataset.id,a);break;case'compare-zoom':dialog.classList.toggle('zoom-details');el.textContent=dialog.classList.contains('zoom-details')?'适合窗口':'放大细节';break;case'sync-video':{const videos=[...dialog.querySelectorAll('video')],pause=videos.some(v=>!v.paused);videos.forEach(v=>{if(pause)v.pause();else{v.currentTime=0;v.play().catch(()=>{});}});break;}case'reset-search':state.query='';state.category='全部';render();break;case'logo-original':replaceLogo('assets/brand-mark.svg');break;case'logo-wide':replaceLogo('assets/brand-wide.svg');break;case'logo-text':replaceLogo(null);break;}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-popup]');if(p){openIntent(p);return;}const context=e.target.closest('[data-context]');if(context){contextMenu(context.dataset.context,context);return;}const param=e.target.closest('[data-param]');if(param){const d=active().draft,key=param.dataset.param;d[key]=key==='count'?Number(param.dataset.value):param.dataset.value;if(key==='type'){d.model=defaultModel(d.type).id;d.quality=d.type==='video'?'1080p':'2K';d.mode='全能参考';}if(key==='model'){d.mode='全能参考';}normalizeDraft(d);d.error=null;refreshComposer();if(['ratio','quality','count'].includes(key)){openIntent($('[data-popup="picture"]'));panel.querySelector(`[data-param="${key}"][data-value="${CSS.escape(String(d[key]))}"]`)?.focus({preventScroll:true});}else closePanel();saveWorkspace();return;}const act=e.target.closest('[data-action]');if(act){handleAction(act.dataset.action,act);if(['mention','reset-advanced'].includes(act.dataset.action))return;}const mention=e.target.closest('[data-mention]');if(mention){insertMention(mention.dataset.mention);closePanel();}const remove=e.target.closest('[data-remove]');if(remove){const d=active().draft,id=remove.dataset.remove;confirmAction({title:'移除参考素材？',message:`将从本次创作移除 @${id}，素材库中的原文件会保留。`,label:'移除素材'}).then(ok=>{if(!ok)return;d.refs=d.refs.filter(r=>r.id!==id);d.error=d.prompt.includes('@'+id)?{text:`@${id} 已移除，请修改高亮的失效引用。`,fix:'refs'}:null;refreshComposer();scheduleSave();});}const view=e.target.closest('[data-view]');if(view)viewOutput(view.dataset.view);const select=e.target.closest('[data-select]');if(select){if(route().name==='library')toggleWork(select.dataset.select);else selectOutput(select.dataset.select);}const cat=e.target.closest('[data-category]');if(cat){state.category=cat.dataset.category;render();}const filter=e.target.closest('[data-library-filter]');if(filter){state.filter=filter.dataset.libraryFilter;render();}if(!e.target.closest('#floating-panel'))closePanel();});
document.addEventListener('input',e=>{if(e.target.id==='prompt'){active().draft.prompt=e.target.value;}if(e.target.id==='negative'){active().draft.negative=e.target.value;updateAdvancedBadge();};if(e.target.id==='workflow-search'){const start=e.target.selectionStart;state.query=e.target.value;main.innerHTML=gallery();$('#workflow-search').focus();$('#workflow-search').setSelectionRange(start,start);}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-files]'))await addFiles([...e.target.files],e.target.dataset.slot);if(e.target.id==='logo-upload'){const f=e.target.files[0];if(f&&f.type.startsWith('image/')&&f.size<2*1024*1024){await replaceLogo(f);toast('已替换 Logo，首页同步使用。');}else toast('请选择小于 2 MB 的 SVG、PNG、WebP 或 JPG。');}});
document.addEventListener('contextmenu',e=>{const output=e.target.closest('[data-output]');if(output){e.preventDefault();contextMenu(output.dataset.output,null,{x:e.clientX,y:e.clientY});}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePanel(true);document.body.classList.remove('nav-open');$('.expanded-writing')?.classList.remove('expanded-writing');document.querySelector('.expand-writing')?.setAttribute('aria-label','展开描述编辑区');}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&$('#prompt')&&!dialog.open&&!e.repeat){e.preventDefault();submit();}if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){const output=e.target.closest('[data-output]');if(output){e.preventDefault();contextMenu(output.dataset.output,output);}}});
document.addEventListener('dragover',e=>{if(e.target.closest('.composer')){e.preventDefault();$('.composer').classList.add('dragover');}});
document.addEventListener('dragleave',e=>{if(e.target.closest('.composer')&&!$('.composer').contains(e.relatedTarget))$('.composer').classList.remove('dragover');});
document.addEventListener('drop',e=>{if(e.target.closest('.composer')){e.preventDefault();$('.composer').classList.remove('dragover');if(active().draft.mode==='首尾帧'){inlineError('请分别选择首帧和尾帧，让起点与终点对应正确。');return;}addFiles([...e.dataTransfer.files]);}});
