// V0.5 — reusable assets, collections and batch operations.
const workspace={assets:[],collections:[],collection:'all',workSelected:new Set(),assetSelected:new Set(),assetFilter:'全部',assetQuery:'',picker:false,pickerSlot:undefined,prompts:[],reviewSeeded:false};
let storageReady=false,saveTimer,exporting=false,importing=false;
const newId=prefix=>prefix+'-'+crypto.randomUUID();
const kindLabel=kind=>({image:'图像',video:'视频',audio:'音频'}[kind]);
const byteLabel=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
function saveRef(r){return {...r,...(r.assetId&&!r.serverAssetId?{src:''}:{})};}
function scheduleSave(){if(!storageReady)return;clearTimeout(saveTimer);saveTimer=setTimeout(saveWorkspace,120);}
async function saveWorkspace(){if(!storageReady)return;const sessions=state.sessions.map(s=>({...s,draft:{...s.draft,error:null,refs:s.draft.refs.map(saveRef)},jobs:s.jobs.map(j=>({...j,snapshot:{...j.snapshot,refs:j.snapshot.refs.map(saveRef)}}))}));try{await writeState({sessions,active:state.active,nextSession,nextJob,refSequence,collections:workspace.collections,reviewSeeded:workspace.reviewSeeded});}catch{toast('本地保存失败，请检查浏览器存储空间；当前页面中的内容仍保留。');}}
async function initializeWorkspace(){
 if(!production){render();return;}
 try{await openStorage();const [assets,saved]=await Promise.all([readAssets(),readState()]);workspace.assets=assets.sort((a,b)=>b.createdAt-a.createdAt).map(a=>({...a,src:URL.createObjectURL(a.blob)}));if(saved?.sessions?.length){state.sessions=saved.sessions;state.active=saved.active;nextSession=saved.nextSession;nextJob=saved.nextJob;refSequence=saved.refSequence;workspace.collections=saved.collections||[];workspace.reviewSeeded=!!saved.reviewSeeded;for(const session of state.sessions){session.liveSubmitting=false;const hydrate=refs=>refs.map(r=>r.serverAssetId?{...r,src:'/api/assets/'+r.serverAssetId+'/file'}:r.assetId?{...r,src:workspace.assets.find(a=>a.id===r.assetId)?.src||''}:r).filter(r=>r.src);session.draft.refs=hydrate(session.draft.refs);if(!session.scope.startsWith('wf:'))normalizeDraft(session.draft);for(const j of session.jobs){j.rerunning=false;j.snapshot.refs=hydrate(j.snapshot.refs);if(j.real&&j.status==='running'&&!j.remoteId&&j.stage?.startsWith('正在上传')){j.status='failed';j.error='素材上传被刷新中断，请重新提交。';j.ended=Date.now();}if(j.status==='running'&&!j.real){j.status='failed';j.reason='interrupted';j.ended=Date.now();}}}}storageReady=true;}
 catch{toast('此浏览器无法保存本地素材。生成布局仍可体验，请使用允许本地存储的浏览器重试。');}
 if(new URLSearchParams(location.search).has('demo')&&!workspace.reviewSeeded){seedReview();workspace.reviewSeeded=true;}
 render();scheduleSave();
}
document.addEventListener('click',scheduleSave);document.addEventListener('input',scheduleSave);document.addEventListener('change',scheduleSave);window.addEventListener('pagehide',()=>saveWorkspace());

const featured=[
 {title:'潮汐之间',tag:'自然光 · 空间',cover:'coast.jpg',prompt:'平静的海面，镜头贴近水面，捕捉蓝绿色海浪的细微纹理。清晨柔和的自然光，低饱和色彩，画面宁静而有呼吸感。'},
 {title:'一座还未抵达的门',tag:'超现实 · 材质',cover:'portal-ocean.png',prompt:'一座透明玻璃取景框矗立在平静海面上，白色薄纱穿过框架，远山笼罩在晨雾中。通透玻璃、真实反射，电影感广角构图。'},
 {title:'光落进森林',tag:'氛围 · 光影',cover:'forest.jpg',prompt:'阳光从高大的树林间斜射下来，照亮苔藓与蕨类植物。纵深构图，细腻自然的纹理，柔和的绿色与温暖高光。'},
 {title:'荒野的形状',tag:'景观 · 构图',cover:'dunes.jpg',prompt:'广阔的红色砂岩荒漠，远处孤立的岩柱，晴朗天空。低角度日光呈现岩壁层次，大尺度空间，纪实电影摄影。'}
];
function discoveries(){return `<div class="discovery"><section><div class="section-heading"><h2>最近上新<span>工作流</span></h2><a class="text-control control" href="#workflows">查看全部 ${I('arrow')}</a></div><div class="new-flow-grid">${workflows.filter(w=>w.live||publicPreview).slice(0,4).map(workflowCard).join('')}</div></section><section><div class="section-heading"><h2>精选作品</h2><span class="quiet-label">演示选集</span></div><div class="featured-grid">${featured.map((f,i)=>`<button class="featured-card" data-action="featured" data-index="${i}"><img src="assets/${f.cover}" alt="${f.title}" loading="lazy"><span class="featured-caption"><strong>${f.title}</strong><small>${f.tag}</small></span><span class="featured-arrow">${I('arrow')}</span></button>`).join('')}</div></section></div>`;}
function creation(){const s=active();return `<div class="creation-shell ${s.jobs.length?'has-jobs':'is-empty'}" aria-label="创作工作区">${s.jobs.length?`<section class="result-feed" id="result-feed" aria-label="生成结果区" tabindex="0"><div class="result-stream">${feedHTML(s)}</div></section>`:''}<div class="composer-slot" id="composer-slot">${composer()}</div>${!s.jobs.length&&!workflow(s)?discoveries():''}<div id="compare-tray" class="compare-tray glass" hidden></div></div>`;}
function landingExtension(){return `<section class="landing-paths"><div class="section-heading"><h2>开始创作</h2></div><div class="landing-path-grid">${[['image','image','图像创作','从一句描述，探索光线、构图与质感。','portal-ocean.png','01'],['video','video','视频创作','组合素材，把想法写成会发生的镜头。','award-poster.jpg','02'],['workflows','grid','工作流','选择一个目标，让步骤为创作服务。','forest.jpg','03']].map(([route,icon,title,desc,cover,n])=>`<a class="landing-path glass" href="studio.html#${route}"><img class="path-image" src="assets/${cover}" alt="" loading="lazy"><div class="path-label"><span>${I(icon)} ${title}</span>${I('arrow')}</div><p>${desc}</p></a>`).join('')}</div></section>`;}

function uploadControl(d,small=false,slot){return `<button class="upload-tile glass ${small?'compact':''}" data-action="open-assets" ${slot!==undefined?`data-slot="${slot}"`:''} aria-label="${slot===0?'选择首帧':slot===1?'选择尾帧':'选择参考素材'}">${I('plus')}<span>${slot===0?'首帧':slot===1?'尾帧':'参考素材'}</span></button>`;}
function referenceLimit(d=active().draft){const w=liveWorkflow();if(w)return w.maxImages+w.maxVideos;return workflow(active())?12:d.mode==='首尾帧'?2:getModel(d).refLimit;}
function allowedKinds(d=active().draft){const w=workflow(active());if(w?.live)return w.maxVideos?['image','video']:['image'];if(d.type==='image'||d.mode==='首尾帧'||w?.mode==='image')return['image'];if(w?.mode==='video')return['video'];return w?['image','video','audio']:getModel(d).kinds;}
function referenceProblem(d,session=active()){if(liveWorkflow(session))return liveProblem(d,liveWorkflow(session));const refs=visibleRefs(d),w=workflow(session),limit=w?12:d.mode==='首尾帧'?2:getModel(d).refLimit,kinds=w?.mode==='video'?['video']:w?.mode==='image'||d.type==='image'||d.mode==='首尾帧'?['image']:w?['image','video','audio']:getModel(d).kinds;if(refs.some(r=>!kinds.includes(r.kind)))return `当前${w?'工作流':getModel(d).name}仅支持${kinds.map(kindLabel).join('、')}参考。请移除不兼容的素材或切换模型。`;if(refs.length>limit)return `当前最多支持 ${limit} 份参考，请移除多余素材。`;if(!w&&d.model==='seedance-2.0'){for(const[kind,n]of[['image',9],['video',3],['audio',3]])if(refs.filter(r=>r.kind===kind).length>n)return `Seedance 2.0 最多使用 ${n} 份${kindLabel(kind)}参考，请移除多余素材。`;}return '';}
function modelOptions(d){return `<div class="option-list model-options">${models.filter(m=>m.type===d.type).map(m=>`<button data-param="model" data-value="${m.id}" class="${m.id===d.model?'chosen':''}"><span><b>${m.name}</b></span>${m.id===d.model?I('check'):''}</button>`).join('')}</div><p class="panel-note">模型选择预览 · 暂未连接服务</p>`;}
function durationMarkup(d){const values=durationOptions(d),value=parseInt(d.duration),index=Math.max(0,values.indexOf(value)),fixed=values.length===1;return `<div class="duration-panel"><div class="duration-readout"><span>视频时长</span><strong><output id="duration-value">${value}</output><small>秒</small></strong></div><input id="duration-range" type="range" min="0" max="${Math.max(1,values.length-1)}" step="1" value="${index}" ${fixed?'disabled':''} aria-label="视频时长" aria-valuetext="${value} 秒${fixed?'，当前模式为固定时长':''}" style="--range-progress:${fixed?100:index/(values.length-1)*100}%"><div class="duration-ends"><button data-duration-index="0" aria-label="最短 ${values[0]} 秒">${values[0]} 秒</button>${!fixed?`<button data-duration-index="${values.length-1}" aria-label="最长 ${values.at(-1)} 秒">${values.at(-1)} 秒</button>`:''}</div></div>`;}

function openIntent(el){if(liveWorkflow())return liveIntent(el);const d=active().draft,m=getModel(d);switch(el.dataset.popup){case'type':popup(el,'',options('type',[['image',''],['video','']],d.type).replace(/<span>image/g,'<span>图像生成').replace(/<span>video/g,'<span>视频生成'));panel.classList.add('compact-options');break;case'model':popup(el,'选择模型',modelOptions(d));break;case'reference':popup(el,'参考方式',options('mode',[['全能参考','组合参考素材'],['首尾帧','定义镜头起点与终点'],['纯文本','仅使用描述']],d.mode));break;case'picture':popup(el,'',pictureOptions(m.ratios,d.ratio,'data-param="ratio"')+segmentOptions('选择分辨率',m.qualities.map(v=>[v,v]),d.quality,'data-param="quality"')+(d.type==='image'?segmentOptions('生成数量',[1,2,3,4].map(v=>[String(v),String(v)]),String(d.count),'data-param="count"'):''));panel.classList.add('picture-popup');positionPanel(el);break;case'output':popup(el,d.type==='video'?'':'生成数量',d.type==='video'?durationMarkup(d):options('count',['1','2','4'].map(v=>[v,'张图像']),d.count));if(d.type==='video')panel.classList.add('duration-popup');break;case'more':popup(el,'高级设置',advancedMarkup(d,workflow(active())));panel.classList.add('advanced-popup');break;}}
function setDuration(index){const d=active().draft,values=durationOptions(d),i=Math.max(0,Math.min(values.length-1,index));d.duration=values[i]+' 秒';const range=$('#duration-range');if(range){range.value=i;range.setAttribute('aria-valuetext',d.duration);range.style.setProperty('--range-progress',(values.length===1?100:i/(values.length-1)*100)+'%');$('#duration-value').textContent=values[i];panel.querySelectorAll('[data-duration-index]').forEach((b,n)=>b.classList.toggle('active',n===i));}const b=$('[data-popup="output"]');if(b)b.innerHTML=I('clock')+d.duration;const gen=$('.generate');if(gen)gen.innerHTML=I('spark')+'演示生成 · 不扣费 '+I('arrow');scheduleSave();}

function assetCard(a,picker){const selected=workspace.assetSelected.has(a.id),compatible=!picker||allowedKinds().includes(a.kind);return `<button class="asset-card glass ${selected?'selected':''}" data-asset="${a.id}" ${compatible?'':'disabled'} aria-pressed="${selected}" aria-label="${selected?'取消选择':'选择'} ${esc(a.name)}"><div class="asset-preview">${a.kind==='image'?`<img src="${a.src}" alt="" loading="lazy">`:a.kind==='video'?`<video src="${a.src}" muted preload="metadata"></video><span class="asset-media-icon">${I('play')}</span>`:`<div class="audio-art">${I('audio')}<span>∣∣∣∣∣∣∣∣∣∣∣∣∣∣∣∣∣∣</span></div>`}<span class="asset-check">${I(selected?'check':'plus')}</span><span class="asset-kind">${kindLabel(a.kind)}</span></div><div class="asset-caption"><strong title="${esc(a.name)}">${esc(a.name)}</strong><small>${byteLabel(a.size)}${compatible?'':' · 当前模式不支持'}</small></div></button>`;}
function assetList(picker=false){const q=workspace.assetQuery.toLowerCase();return workspace.assets.filter(a=>(workspace.assetFilter==='全部'||workspace.assetFilter===kindLabel(a.kind))&&a.name.toLowerCase().includes(q));}
function assetPanel(picker=false){const list=assetList(picker);return `<div class="asset-toolbar ${picker?'':'library-head compact-head asset-head'}">${picker?'':'<h1>素材库</h1>'}<div class="category-tabs" aria-label="素材类型">${['全部','图像','视频','音频'].map(t=>`<button class="category ${workspace.assetFilter===t?'active':''}" data-asset-filter="${t}">${t}</button>`).join('')}</div><label class="searchbox glass">${I('search')}<input id="asset-search" value="${esc(workspace.assetQuery)}" placeholder="搜索素材名称" aria-label="搜索素材"></label>${picker?'':assetImportLabel()}</div><div class="asset-library-content" data-asset-drop>${list.length?`<div class="asset-grid">${list.map(a=>assetCard(a,picker)).join('')}</div>`:`<div class="asset-empty"><span class="empty-icon">${I('folder')}</span><h2>${workspace.assets.length?'没有匹配的素材':'好素材，值得反复使用。'}</h2><p>${workspace.assets.length?'换个关键词或清除筛选。':'把图片、视频、音频拖到这里，或批量导入。<br>以后创作时，直接从这里选。'}</p>${workspace.assets.length?B('清除筛选','reset-assets','button'):assetImportLabel()}</div>`}</div><div class="asset-footer"><span id="asset-selection-count">已选 ${workspace.assetSelected.size} 项 <small>· 保存在当前浏览器</small></span><div>${B('全选可用项','select-assets','small-button')}${workspace.assetSelected.size?B('清空','clear-assets','small-button'):''}${picker?B('使用所选素材','attach-assets','button primary',workspace.assetSelected.size?'':'disabled'):B('带入创作','assets-create','button primary',workspace.assetSelected.size?'':'disabled')}${!picker?B('移除所选','delete-assets','small-button',workspace.assetSelected.size?'':'disabled'):''}</div></div>`;}
function assetImportLabel(){return `<label class="small-button control primary file-import">${I('plus')}批量导入素材<input type="file" data-vault-files multiple accept="image/*,video/*,audio/*" aria-label="批量导入素材"></label>`;}
function assetLibrary(){workspace.picker=false;return `<section class="library-page asset-page"><div id="asset-panel">${assetPanel()}</div></section>`;}
function openAssetPicker(slot){closePanel();workspace.picker=true;workspace.pickerSlot=slot===undefined?undefined:Number(slot);workspace.assetSelected.clear();workspace.assetQuery='';workspace.assetFilter=workspace.pickerSlot===undefined?'全部':'图像';modal(workspace.pickerSlot===0?'选择首帧':workspace.pickerSlot===1?'选择尾帧':'选择参考素材',`<div class="picker-intro"><span>从素材库选取，或导入新的素材。</span>${assetImportLabel()}</div><div id="asset-panel">${assetPanel(true)}</div>`,'asset-dialog');}
function refreshAssets(){const box=$('#asset-panel');if(box){const top=box.querySelector('.asset-library-content')?.scrollTop||0,focused=document.activeElement?.id==='asset-search',pos=$('#asset-search')?.selectionStart;box.innerHTML=assetPanel(workspace.picker);if(box.querySelector('.asset-library-content'))box.querySelector('.asset-library-content').scrollTop=top;if(focused){$('#asset-search').focus();$('#asset-search').setSelectionRange(pos,pos);}}}
async function importAssets(files){if(importing){toast('正在导入上一批素材，请稍候。');return[];}if(!storageReady){toast('本地素材存储不可用，请检查浏览器设置。');return[];}importing=true;const added=[],errors=[];let duplicates=0;try{for(const file of files){const kind=file.type.split('/')[0];if(!['image','video','audio'].includes(kind)){errors.push(file.name+'：请选择图像、视频或音频');continue;}const limit={image:40,video:200,audio:50}[kind];if(file.size>limit*1048576){errors.push(file.name+'：超过 '+limit+' MB，请压缩后再导入');continue;}const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');const old=workspace.assets.find(a=>a.hash===hash);if(old){added.push(old);duplicates++;continue;}const a={id:newId('asset'),kind,name:file.name,size:file.size,hash,createdAt:Date.now(),blob:file};try{await putAsset(a);a.src=URL.createObjectURL(file);workspace.assets.unshift(a);added.push(a);}catch{errors.push(file.name+'：保存失败，请释放浏览器存储空间后重试');}}
 }finally{importing=false;}
 for(const a of added)if(!workspace.picker||allowedKinds().includes(a.kind)){if(workspace.pickerSlot!==undefined)workspace.assetSelected.clear();workspace.assetSelected.add(a.id);}
 refreshAssets();if(route().name==='assets'&&!dialog.open)render();
 if(errors.length){let e=$('#import-error');if(!e){$('#asset-panel')?.insertAdjacentHTML('afterbegin','<div id="import-error" class="inline-error" role="alert"></div>');e=$('#import-error');}if(e)e.textContent=errors.slice(0,5).join('；');else toast(errors[0]);}
 if(added.length)toast(`已导入 ${added.length-duplicates} 份素材${duplicates?'，复用 '+duplicates+' 份重复素材':''}。`);return added;
}
function attachAsset(a,d=active().draft,slot){if(slot!==undefined)d.refs=d.refs.filter(r=>r.slot!==slot);if(d.refs.some(r=>r.assetId===a.id&&r.slot===slot))return;const kind=a.kind;d.refs.push({id:({image:'图片',video:'视频',audio:'音频'}[kind])+(++refSequence[kind]),assetId:a.id,kind,name:a.name,src:a.src,...(slot!==undefined?{slot}:{}),local:true});}
function attachSelected(create=false){const chosen=workspace.assets.filter(a=>workspace.assetSelected.has(a.id));if(!chosen.length)return;if(create){const type=chosen.some(a=>a.kind!=='image')?'video':'image';makeSession('model',type);}const d=active().draft,old=[...d.refs];if(d.mode==='纯文本')d.mode='全能参考';if(workspace.pickerSlot!==undefined&&chosen.length!==1){toast('首帧或尾帧一次选择一张图片。');return;}chosen.forEach(a=>attachAsset(a,d,workspace.pickerSlot));normalizeDraft(d);const problem=referenceProblem(d);if(problem){d.refs=old;toast(problem);return;}d.error=null;workspace.picker=false;workspace.pickerSlot=undefined;dialog.close();location.hash='session/'+active().id;render();$('#prompt')?.focus();scheduleSave();toast(`已添加 ${chosen.length} 份参考，可点击缩略图插入 @ 引用。`);}
async function addFiles(files,slot){const added=await importAssets(files),d=active().draft,old=[...d.refs];if(d.mode==='纯文本')d.mode='全能参考';added.forEach(a=>attachAsset(a,d,slot===undefined?undefined:Number(slot)));normalizeDraft(d);const problem=referenceProblem(d);if(problem){d.refs=old;inlineError(problem+' 素材已保存在素材库。','refs-library');}else{d.error=null;refreshComposer();}scheduleSave();}

function filteredWorks(){return allOutputs().filter(({o})=>(state.filter==='全部'||o.type===(state.filter==='图像'?'image':'video'))&&(workspace.collection==='all'||workspace.collection==='none'&&!o.collectionId||o.collectionId===workspace.collection));}
function collectionName(id){return workspace.collections.find(c=>c.id===id)?.name||'未分类';}
function workTitle(j,o){return (j.snapshot.prompt|| (o.type==='video'?'视频创作':'图像创作')).split(/[。！？\n]/)[0].slice(0,22);}
function library(){const all=filteredWorks(),total=allOutputs().length;return `<section class="library-page works-page"><header class="library-head compact-head"><h1>我的作品</h1><div class="category-tabs" aria-label="作品类型">${['全部','图像','视频'].map(t=>`<button class="category ${state.filter===t?'active':''}" data-library-filter="${t}" aria-pressed="${state.filter===t}">${t}</button>`).join('')}</div><div class="head-actions">${B('全选','select-works','small-button')}${B(I('folder')+'分类','manage-collections','small-button')}${B(I('plus'),'new-collection','icon-button','aria-label="新建分类"')}</div></header><div class="collection-tabs" aria-label="作品分类"><button data-collection="all" class="collection-tab ${workspace.collection==='all'?'active':''}">全部作品</button><button data-collection="none" class="collection-tab ${workspace.collection==='none'?'active':''}">未分类</button>${workspace.collections.map(c=>`<button data-collection="${c.id}" class="collection-tab ${workspace.collection===c.id?'active':''}">${I('folder')}${esc(c.name)}</button>`).join('')}</div>${all.length?`<div class="works-grid">${all.map(({o,j},i)=>`<div class="work-item">${outputHTML(o,j,i)}<div class="work-caption"><strong>${esc(workTitle(j,o))}</strong><p>${esc(j.snapshot.prompt.slice(0,78)||'使用参考素材创作')}${j.snapshot.prompt.length>78?'…':''}</p></div></div>`).join('')}</div>`:`<div class="useful-empty"><h2>${total?'这个分类还没有作品':'从第一段描述开始'}</h2><p>${total?'选择作品，即可批量移入分类。':'完成后的结果会自动保存在这里。'}</p>${total?B('查看全部作品','all-works','button'):'<a href="#workflows" class="button primary">开始创作 '+I('arrow')+'</a>'}</div>`}</section><div id="work-batch-bar" class="work-batch-bar glass" ${workspace.workSelected.size?'':'hidden'}>${workBatchMarkup()}</div>`;}

function workBatchMarkup(){const n=workspace.workSelected.size;return `<strong>已选 ${n} 项</strong>${B('批量导出 ZIP','export-works','small-button primary',exporting?'disabled':'')}${B('移入分类','move-works','small-button')}${B('并排对比','compare-works','small-button',n<2||n>4?'disabled':'')}${B('清空选择','clear-works','small-button')}`;}
function syncWorkSelection(){const ids=allOutputs().map(({o})=>o.id);for(const id of workspace.workSelected)if(!ids.includes(id))workspace.workSelected.delete(id);$$('[data-output]').forEach(el=>{const on=workspace.workSelected.has(el.dataset.output);el.classList.toggle('selected',on);const button=el.querySelector('[data-select]');button.classList.toggle('active',on);button.innerHTML=I(on?'check':'plus')+'<span>选择</span>';button.setAttribute('aria-label',(on?'取消选择':'选择')+'作品');button.setAttribute('aria-pressed',on);});const bar=$('#work-batch-bar');if(bar){bar.hidden=!workspace.workSelected.size;bar.innerHTML=workBatchMarkup();}}
function toggleWork(id){workspace.workSelected.has(id)?workspace.workSelected.delete(id):workspace.workSelected.add(id);syncWorkSelection();}
function collectionForm(id){const c=workspace.collections.find(c=>c.id===id);modal(c?'重命名分类':'新建分类',`<form id="collection-form" data-id="${c?.id||''}"><label for="collection-name">分类名称</label><input id="collection-name" class="solid-input" maxlength="30" value="${esc(c?.name||'')}" placeholder="例如：品牌短片、产品海报" required><p id="collection-error" class="form-error" role="alert"></p><div class="dialog-actions">${B('取消','close-dialog','small-button')}<button type="submit" class="button primary">${c?'保存名称':'创建分类'}</button></div></form>`,'small-dialog');$('#collection-name').focus();}
function manageCollections(){modal('管理分类',`${workspace.collections.length?`<div class="collection-list">${workspace.collections.map(c=>`<div><span>${I('folder')}${esc(c.name)}</span>${B('重命名','rename-collection','small-button',`data-id="${c.id}"`)}${B('移除分类','delete-collection','small-button',`data-id="${c.id}"`)}</div>`).join('')}</div><p class="panel-note">移除分类后，里面的作品会保留在「未分类」。</p>`:'<p class="panel-note">按项目或用途建立分类，让作品更容易找到。</p>'}${B('新建分类','new-collection','button primary')}`,'small-dialog');}
function moveWorks(){modal('移入分类',`<div class="option-list"><button data-move-collection="">未分类</button>${workspace.collections.map(c=>`<button data-move-collection="${c.id}">${I('folder')}${esc(c.name)}</button>`).join('')}</div>${B('新建分类','new-collection','small-button')}`,'small-dialog');}
async function exportWorks(){if(exporting)return;const selected=allOutputs().filter(({o})=>workspace.workSelected.has(o.id));if(!selected.length)return;exporting=true;syncWorkSelection();toast('正在打包 '+selected.length+' 件作品…');try{const files=[],manifest=[];for(const [{o,j},i] of selected.map((x,i)=>[x,i])){const response=await fetch(o.src);if(!response.ok)throw new Error('无法读取作品文件，请稍后重试。');const type=o.type==='video'?'mp4':o.src.endsWith('.png')?'png':'jpg',name=`${String(i+1).padStart(2,'0')}-${o.id}.${type}`;files.push({name,data:new Uint8Array(await response.arrayBuffer())});manifest.push({file:name,prompt:j.snapshot.prompt,model:j.snapshot.workflowId?null:getModel(j.snapshot).name,workflow:j.snapshot.workflowId?(workflows.find(w=>w.id===j.snapshot.workflowId)?.name||j.snapshot.workflowId):null,parameters:j.snapshot,collection:collectionName(o.collectionId),demo:!j.real});}files.push({name:'作品说明.json',data:JSON.stringify(manifest.map(({parameters,...rest})=>({...rest,parameters:{ratio:parameters.ratio,quality:parameters.quality,duration:parameters.duration,count:parameters.count,negative:parameters.negative||'',workflowId:parameters.workflowId||null,advanced:parameters.advanced||{},workflowParameters:parameters.liveSettings||null}})),null,2)});downloadBlob(createZip(files),'映序-作品集-'+new Date().toISOString().slice(0,10)+'.zip');toast('已导出 '+selected.length+' 件作品和提示词说明。');}catch(e){toast('导出失败：'+e.message+' 已保留选择，可重试。');}finally{exporting=false;syncWorkSelection();}}

function promptRows(text){return text.replace(/^\uFEFF/,'').split(/\r?\n/).map(t=>t.trim()).filter(Boolean);}
function batchPrompts(){workspace.prompts=[];modal('批量导入提示词',`<p class="dialog-description">每行一条提示词。先预览和修改，再按当前模型与参数逐条创建任务。</p><label class="file-import control small-button">${I('plus')}选择 TXT / CSV / JSON<input type="file" data-prompt-files multiple accept=".txt,.csv,.json" aria-label="导入提示词文件"></label><textarea id="batch-prompt-input" class="solid-input" rows="6" placeholder="海边的玻璃建筑，柔和晨光\n山谷中的云海，广角远景"></textarea><p id="batch-error" class="form-error" role="alert"></p><div id="batch-preview"></div><div class="dialog-actions">${B('预览任务','preview-prompts','small-button')}${B('创建任务','run-prompts','button primary','disabled')}</div>`,'batch-dialog');}
function parsePromptFile(text,name){if(name.toLowerCase().endsWith('.json')){const obj=JSON.parse(text),list=Array.isArray(obj)?obj:obj.prompts;if(!Array.isArray(list))throw new Error('JSON 请使用字符串数组或 {"prompts": [...]}。');return list.map(v=>typeof v==='string'?v:typeof v?.prompt==='string'?v.prompt:'').filter(Boolean);}if(name.toLowerCase().endsWith('.csv')){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV 引号未闭合，请检查文件。');row.push(cell);if(row.some(Boolean))rows.push(row);if(!rows.length)return[];const header=rows[0].map(v=>v.replace(/^\uFEFF/,'').trim().toLowerCase()),col=header.findIndex(v=>['prompt','提示词','描述'].includes(v));return(col>=0?rows.slice(1):rows).map(r=>r[col>=0?col:0]?.trim()).filter(Boolean);}return promptRows(text);}
function previewPrompts(){const prompts=promptRows($('#batch-prompt-input').value);workspace.prompts=[];if(!prompts.length||prompts.length>50||prompts.some(p=>p.length>6000)){ $('#batch-error').textContent=!prompts.length?'先粘贴或导入提示词。':prompts.length>50?'一次最多导入 50 条，请拆分后重试。':'单条描述最多 6000 字，请缩短后重试。';$('[data-action="run-prompts"]').disabled=true;return;}workspace.prompts=prompts;$('#batch-error').textContent='';$('#batch-preview').innerHTML=`<div class="batch-summary"><strong>${prompts.length} 个任务</strong><span>${liveWorkflow()?liveWorkflow().name+' · 使用当前算力卡':getModel(active().draft).name+' · 演示任务'}</span></div><ol>${prompts.map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`;const b=$('[data-action="run-prompts"]');b.disabled=false;b.textContent=`生成 ${prompts.length} 个任务 · ${liveWorkflow()?'算力卡计费':'演示'}`;}
async function runPrompts(){const list=[...workspace.prompts];if(!list.length)return;const d=active().draft,problem=referenceProblem(d);if(problem){$('#batch-error').textContent=problem;return;}if(d.mode==='首尾帧'&&(!d.refs.some(r=>r.slot===0)||!d.refs.some(r=>r.slot===1))){$('#batch-error').textContent='请先在创作区补齐首帧和尾帧。';return;}const ids=visibleRefs(d).map(r=>'@'+r.id),missing=list.flatMap(p=>(p.match(/@(图片|视频|音频)\d+/g)||[]).filter(t=>!ids.includes(t)));if(missing.length){$('#batch-error').textContent=[...new Set(missing)].join('、')+' 没有对应素材，请修改后重新预览。';return;}dialog.close();const session=active();for(const prompt of list){const ok=await submit({...d,prompt,refs:[...d.refs]},session);if(ok===false)break;}workspace.prompts=[];scheduleSave();toast('已提交批量任务，每条提示词独立一栏。');}

function handleWorkspaceAction(a,el){switch(a){case'save-output':{const found=findOutput(el.dataset.id);if(found)(async()=>{try{const response=await fetch(found.o.src);if(!response.ok)throw new Error();const blob=await response.blob();await importAssets([new File([blob],found.o.id+'.'+(found.o.type==='video'?'mp4':found.o.src.endsWith('.png')?'png':'jpg'),{type:blob.type})]);}catch{toast('保存失败，请稍后重试。');}})();closePanel();break;}case'open-assets':openAssetPicker(el.dataset.slot);break;case'attach-assets':attachSelected();break;case'assets-create':workspace.pickerSlot=undefined;attachSelected(true);break;case'select-assets':{const list=assetList(workspace.picker).filter(a=>!workspace.picker||allowedKinds().includes(a.kind));if(workspace.pickerSlot!==undefined){toast('首帧或尾帧一次选择一张图片。');break;}const all=list.every(a=>workspace.assetSelected.has(a.id));list.forEach(a=>all?workspace.assetSelected.delete(a.id):workspace.assetSelected.add(a.id));refreshAssets();break;}case'clear-assets':workspace.assetSelected.clear();refreshAssets();break;case'reset-assets':workspace.assetQuery='';workspace.assetFilter='全部';refreshAssets();break;case'delete-assets':{const selected=workspace.assets.filter(a=>workspace.assetSelected.has(a.id)),used=state.sessions.flatMap(s=>[...s.draft.refs,...s.jobs.flatMap(j=>j.snapshot.refs)]).map(r=>r.assetId);if(selected.some(a=>used.includes(a.id))){toast('所选素材仍被草稿或任务引用，已保留。可先清空选择，再选择未使用素材。');break;}(async()=>{try{for(const a of selected){await deleteAsset(a.id);URL.revokeObjectURL(a.src);workspace.assets=workspace.assets.filter(x=>x.id!==a.id);}workspace.assetSelected.clear();render();toast('已移除 '+selected.length+' 份未使用素材。');}catch{toast('移除失败，请重试。');}})();break;}case'featured':{const f=featured[Number(el.dataset.index)];modal(f.title,`<img class="featured-preview" src="assets/${f.cover}" alt="${f.title}"><p class="featured-prompt">${esc(f.prompt)}</p><div class="dialog-actions">${B('使用这段描述','use-featured','button primary',`data-index="${el.dataset.index}"`)}${B('保存到素材库','save-featured','small-button',`data-index="${el.dataset.index}"`)}</div>`,'featured-dialog');break;}case'use-featured':{const f=featured[Number(el.dataset.index)];active().draft.prompt=f.prompt;dialog.close();refreshComposer();$('#prompt').focus();break;}case'save-featured':{const f=featured[Number(el.dataset.index)];(async()=>{const response=await fetch('assets/'+f.cover);const blob=await response.blob();await importAssets([new File([blob],f.title+'.'+f.cover.split('.').at(-1),{type:blob.type})]);})();break;}case'new-collection':collectionForm();break;case'rename-collection':collectionForm(el.dataset.id);break;case'manage-collections':manageCollections();break;case'delete-collection':{const id=el.dataset.id;workspace.collections=workspace.collections.filter(c=>c.id!==id);allOutputs().forEach(({o})=>{if(o.collectionId===id)delete o.collectionId;});if(workspace.collection===id)workspace.collection='all';render();manageCollections();scheduleSave();toast('分类已移除，作品保留在未分类中。');break;}case'all-works':workspace.collection='all';state.filter='全部';render();break;case'select-works':{const list=filteredWorks(),all=list.every(({o})=>workspace.workSelected.has(o.id));list.forEach(({o})=>all?workspace.workSelected.delete(o.id):workspace.workSelected.add(o.id));syncWorkSelection();break;}case'clear-works':workspace.workSelected.clear();syncWorkSelection();break;case'move-works':moveWorks();break;case'export-works':exportWorks();break;case'compare-works':{const selected=[...workspace.workSelected],types=new Set(selected.map(id=>findOutput(id)?.o.type));if(types.size!==1){toast('请选同一类型的 2–4 个作品进行对比。');break;}state.selected=new Set(selected);compare();break;}case'batch-prompts':batchPrompts();break;case'preview-prompts':previewPrompts();break;case'run-prompts':runPrompts();break;default:return false;}return true;}
document.addEventListener('click',e=>{const asset=e.target.closest('[data-asset]');if(asset){const id=asset.dataset.asset;if(workspace.assetSelected.has(id))workspace.assetSelected.delete(id);else{if(workspace.pickerSlot!==undefined)workspace.assetSelected.clear();workspace.assetSelected.add(id);}refreshAssets();}const filter=e.target.closest('[data-asset-filter]');if(filter){workspace.assetFilter=filter.dataset.assetFilter;refreshAssets();}const coll=e.target.closest('[data-collection]');if(coll){workspace.collection=coll.dataset.collection;render();}const move=e.target.closest('[data-move-collection]');if(move){allOutputs().filter(({o})=>workspace.workSelected.has(o.id)).forEach(({o})=>{o.collectionId=move.dataset.moveCollection||null;});dialog.close();workspace.workSelected.clear();render();scheduleSave();toast('分类已更新。');}const duration=e.target.closest('[data-duration-index]');if(duration)setDuration(Number(duration.dataset.durationIndex));});
document.addEventListener('input',e=>{if(e.target.id==='duration-range')setDuration(Number(e.target.value));if(e.target.id==='asset-search'){workspace.assetQuery=e.target.value;refreshAssets();}if(e.target.id==='batch-prompt-input'){workspace.prompts=[];$('#batch-preview').innerHTML='';$('[data-action="run-prompts"]').disabled=true;$('[data-action="run-prompts"]').textContent='创建任务';}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-vault-files]'))await importAssets([...e.target.files]);if(e.target.matches('[data-prompt-files]')){workspace.prompts=[];$('#batch-preview').innerHTML='';$('[data-action="run-prompts"]').disabled=true;try{const rows=[];for(const file of e.target.files){if(file.size>1048576)throw new Error(file.name+' 超过 1 MB，请拆分文件。');rows.push(...parsePromptFile(await file.text(),file.name));}$('#batch-prompt-input').value=rows.map(t=>t.replace(/\r?\n/g,' ')).join('\n');previewPrompts();}catch(err){$('#batch-error').textContent=err instanceof SyntaxError?'JSON 格式有误，请使用字符串数组，例如：["海边晨光", "森林小径"]，修改后重新导入。':err.message;}}});
document.addEventListener('submit',e=>{if(e.target.id!=='collection-form')return;e.preventDefault();const name=$('#collection-name').value.trim(),id=e.target.dataset.id;if(!name){$('#collection-error').textContent='请输入分类名称。';return;}if(workspace.collections.some(c=>c.name===name&&c.id!==id)){ $('#collection-error').textContent='已有同名分类，请换一个名称。';return;}if(id)workspace.collections.find(c=>c.id===id).name=name;else workspace.collections.push({id:newId('collection'),name});dialog.close();render();scheduleSave();toast(id?'分类名称已保存。':'分类已创建，可选择作品批量移入。');});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-asset-drop]')){e.preventDefault();e.target.closest('[data-asset-drop]').classList.add('dragover');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-asset-drop]')?.classList.remove('dragover'));
document.addEventListener('drop',e=>{if(e.target.closest('[data-asset-drop]')){e.preventDefault();e.target.closest('[data-asset-drop]').classList.remove('dragover');importAssets([...e.dataTransfer.files]);}});

// Review URLs load explicitly labelled local examples; no model is called.
function seedReview(){const mode=new URLSearchParams(location.search).get('demo');if(!production||!['results','progress','error'].includes(mode))return;resolveSession();const s=active();s.draft.prompt='一组安静的自然景观，柔和晨光、真实材质、低饱和色彩。';s.draft.count=4;for(let n=0;n<(mode==='results'?2:1);n++){const snap={...s.draft,refs:[]};if(n){snap.prompt='让画面更开阔，突出自然纹理与空间层次，保持柔和的电影光线。';snap.count=2;}const j={id:'j'+nextJob++,snapshot:snap,cost:cost(snap),started:Date.now()-(mode==='progress'?4500:DEMO_DURATION),outputs:[],status:'running',ended:null};s.jobs.push(j);if(mode==='results')complete(j);if(mode==='error'){j.status='failed';j.ended=Date.now();}}s.title=s.jobs[0].snapshot.prompt.slice(0,28);s.draft.prompt='';}
function viewportHeight(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||innerHeight)+'px');}viewportHeight();window.visualViewport?.addEventListener('resize',viewportHeight);
await initializeWorkspace();if(production)setInterval(tickJobs,350);

function advancedMarkup(d,w){return `${!w?`<details class="mobile-model-disclosure"><summary>模型 · ${getModel(d).name}</summary>${modelOptions(d)}</details>`:''}${advancedFields(d,w)}<section class="advanced-negative"><label class="intent-label" for="negative">反向提示词 <span>可选</span></label><textarea id="negative" class="negative-input" placeholder="写下要避免的元素，如：水印、背景杂物" maxlength="2000" rows="3">${esc(d.negative||'')}</textarea></section><div class="advanced-footer">${B('恢复默认','reset-advanced','text-control')}${B('完成','close-panel','button primary')}</div>`;}
function updateAdvancedBadge(){const b=$('.settings-count');if(!b)return;const n=advancedCount(active().draft,workflow(active()));b.hidden=!n;b.textContent=n;}
function setAdvanced(key,value){const d=active().draft;d.advanced={...(d.advanced||{}),[key]:value};d.advanced=advancedValues(d,workflow(active()));const range=$(`[data-advanced="${key}"]`);if(range){range.style.setProperty('--range-progress',d.advanced[key]+'%');range.setAttribute('aria-valuetext',d.advanced[key]+'%');$(`#value-${key}`).innerHTML=d.advanced[key]+'<small>%</small>';}panel.querySelectorAll(`[data-advanced-choice="${key}"]`).forEach(b=>{const on=b.dataset.value===d.advanced[key];b.classList.toggle('chosen',on);b.setAttribute('aria-pressed',on);});updateAdvancedBadge();scheduleSave();}
function showJobSettings(id){if(findJob(id)?.j.real)return liveJobSettings(id);const found=findJob(id);if(!found)return;const d=found.j.snapshot,w=workflows.find(w=>w.id===d.workflowId)||workflow(found.s);modal('本次生成参数',`<p class="settings-context">${esc(w?.name||getModel(d).name)}</p><dl class="parameter-summary"><div><dt>画面</dt><dd>${d.ratio} · ${d.quality}</dd></div><div><dt>${d.type==='video'?'时长':'数量'}</dt><dd>${d.type==='video'?d.duration:d.count+' 张'}</dd></div></dl><div class="saved-negative"><span>反向提示词</span><p>${esc(d.negative||'未设置')}</p></div><div class="dialog-actions">${B('用这些参数重新编辑','reedit','button primary',`data-job="${id}"`)}</div>`,'small-dialog');}
document.addEventListener('click',e=>{const choice=e.target.closest('[data-advanced-choice]');if(choice)setAdvanced(choice.dataset.advancedChoice,choice.dataset.value);});
document.addEventListener('input',e=>{if(e.target.matches('[data-advanced]'))setAdvanced(e.target.dataset.advanced,Number(e.target.value));});

// Real workflow bridge. UI layout and reusable asset storage remain in app.js.
function liveWorkflow(s=active()){const w=workflow(s);return w?.live?w:null;}
function qualityName(value){return ({0.2:'预览',0.5:'标准',1:'精细'})[value]||'自定义';}
function segmentOptions(label,items,value,attrs){return `<section class="picture-section"><h3>${label}</h3><div class="segmented-options">${items.map(([v,text])=>`<button class="segment ${String(value)===String(v)?'selected':''}" ${attrs} data-value="${v}" aria-pressed="${String(value)===String(v)}">${text}</button>`).join('')}</div></section>`;}
function pictureOptions(ratios,value,attrs){return segmentOptions('选择比例',ratios.map(v=>{const[a,b]=v.split(':').map(Number);return[v,`<span class="ratio-symbol" aria-hidden="true" style="width:${Math.round(a>=b?16:16*a/b)}px;height:${Math.round(b>=a?16:16*b/a)}px"></span><span>${v}</span>`]}),value,attrs);}
function livePicture(w,v){return(w.id==='h3-reference'?pictureOptions(w.fields.find(f=>f.key==='ratio').options,v.ratio,'data-live-choice="ratio"')+segmentOptions('选择清晰度',[[0.2,'预览'],[0.5,'标准'],[1,'精细']],v.megapixels,'data-live-choice="megapixels"'):`<section class="picture-section"><h3>画面比例</h3><div class="source-ratio"><span class="ratio-symbol" aria-hidden="true"></span>沿用原视频</div></section>`+segmentOptions('选择清晰度 · 画面长边',[[384,'384 px'],[512,'512 px'],[768,'768 px'],[1024,'1024 px']],v.long_side,'data-live-choice="long_side"'))+(w.id==='h3-reference'?`<p class="resolution-readout">${qualityName(v.megapixels)} · 约 ${estimatedSize(v)} px</p>`:'');}
function estimatedSize(v){const[a,b]=v.ratio.split(':').map(Number),pixels=v.megapixels*1024*1024;return Math.round(Math.sqrt(pixels*a/b)/32)*32+' × '+Math.round(Math.sqrt(pixels*b/a)/32)*32;}
document.addEventListener('click',e=>{const choice=e.target.closest('[data-live-choice]');if(!choice)return;const w=liveWorkflow(),f=w.fields.find(f=>f.key===choice.dataset.liveChoice);liveSettings(active().draft,w)[f.key]=typeof f.default==='number'?Number(choice.dataset.value):choice.dataset.value;liveIntent($('[data-popup="picture"]'));refreshComposer();scheduleSave();});
function liveSettings(d,w){d.liveSettings||={};for(const f of w.fields)if(d.liveSettings[f.key]===undefined)d.liveSettings[f.key]=f.default;return d.liveSettings;}
function liveProblem(d,w,required=false){const refs=d.refs||[];if(refs.some(r=>r.available===false))return '原素材文件已被移除。请移除缺失项并重新导入同一份素材。';if(refs.some(r=>!['image','video'].includes(r.kind)))return '这两个工作流只接收图片和 MP4 视频。';for(const[k,lo,hi]of[['image','minImages','maxImages'],['video','minVideos','maxVideos']]){const n=refs.filter(r=>r.kind===k).length;if(n>w[hi]||required&&n<w[lo])return `${w.name}需要 ${w[lo]}–${w[hi]} 份${k==='image'?'图片':'视频'}素材。`;}return '';}
function liveComposer(s,w){const d=s.draft;d.type='video';d.mode='全能参考';const v=liveSettings(d,w),hasJobs=s.jobs.length;return `<section class="composer glass" aria-label="创作操作区"><div class="workflow-strip"><a class="control small-button" href="#workflows">${I('back')}工作流</a><span>${w.name}</span></div>${refsMarkup(d)}<div class="writing-row"><div class="writing-area"><label for="prompt" class="sr-only">镜头描述</label><textarea id="prompt" spellcheck="false" maxlength="6000" placeholder="${esc(w.placeholder)}" rows="${hasJobs?3:5}">${esc(d.prompt)}</textarea></div><button class="expand-writing icon-button" data-action="expand" aria-label="展开描述编辑区">${I('expand')}</button></div>${issueHTML(d)}<div class="composer-controls"><div class="control-cluster">${!d.refs.length?uploadControl(d):''}<button class="intent-control" data-popup="picture">${w.id==='h3-reference'?`${v.ratio} · ${qualityName(v.megapixels)}`:`原片比例 · ${v.long_side} px`}${I('down')}</button><button class="intent-control duration-control" data-popup="output" aria-label="视频时长">${I('clock')}${w.id==='h3-reference'?'约':'前'} ${v.duration} 秒</button><button class="intent-control extra-control" data-popup="more" aria-label="高级设置">${I('settings')}<span>高级</span></button>${d.refs.length?B('@','mention','intent-control','aria-label="引用素材"'):''}</div><button class="button primary generate" data-action="generate" ${s.liveSubmitting?'disabled':''}>${I('spark')}${s.liveSubmitting?'正在提交…':'生成 · 算力卡计费'} ${I('arrow')}</button></div></section><div class="composer-foot"><span>${!hasJobs?B('填入一段示例','example','text-control'):''}</span><span>费用按当前卡计时，本站不收积分</span></div><div class="composer-utilities">${B(I('folder')+'素材库','open-assets','text-control')}${B(I('checklist')+'批量提示词','batch-prompts','text-control')}</div>`;}
function liveField(f,v){const name='live-'+f.key;return `<label class="live-field" for="${name}"><span>${esc(f.label)}</span>${f.options?`<select id="${name}" data-live-field="${f.key}">${f.options.map(o=>`<option value="${o}" ${String(v)===String(o)?'selected':''}>${f.key==='steps'?o+' 步':({match:'适配画面',max:'完整参考'})[o]||o}</option>`).join('')}</select>`:`<input id="${name}" data-live-field="${f.key}" required type="number" ${f.key==='seed'?'title="填 -1 使用随机值；填写固定整数用于复现"':''} min="${f.min}" max="${f.max}" step="${f.step}" value="${v}">`}</label>`;}
function liveIntent(el){const w=liveWorkflow(),d=active().draft,v=liveSettings(d,w),kind=el.dataset.popup;if(kind==='picture'){popup(el,'',livePicture(w,v));panel.classList.add('picture-popup');positionPanel(el);return;}if(kind==='output'){const f=w.fields.find(f=>f.key==='duration');popup(el,'',`<div class="duration-panel"><div class="duration-readout"><span>${w.id==='bernini-edit'?'处理前几秒':'视频时长（约）'}</span><strong><output id="live-duration-value">${v.duration}</output><small>秒</small></strong></div><input data-live-field="duration" id="live-duration" aria-label="视频时长" type="range" min="${f.min}" max="${f.max}" step="1" value="${v.duration}" style="--range-progress:${(v.duration-f.min)/(f.max-f.min)*100}%"><div class="duration-ends"><span>${f.min} 秒</span><span>${f.max} 秒</span></div></div>`);panel.classList.add('duration-popup');return;}
const keys=kind==='picture'?(w.id==='h3-reference'?['ratio','megapixels']:['long_side']):w.fields.filter(f=>!f.hidden).map(f=>f.key).filter(k=>!['ratio','megapixels','long_side','duration'].includes(k));
const neg=kind==='more'&&w.negative?`<section class="advanced-negative"><label class="intent-label" for="negative">反向提示词 <span>可选</span></label><textarea id="negative" class="negative-input" placeholder="写下要避免的元素，如：水印、画面闪烁" rows="3">${esc(d.negative||'')}</textarea></section>`:'';
popup(el,kind==='picture'?'画面设置':'高级设置',`${neg}<div class="live-fields">${w.fields.filter(f=>keys.includes(f.key)).map(f=>liveField(f,v[f.key])).join('')}</div><p class="live-form-status" role="alert"></p><div class="advanced-footer">${B('恢复默认','live-reset','text-control')}${B('完成','close-panel','button primary')}</div>`);panel.classList.add('advanced-popup');}
async function liveApi(path,options){if(publicPreview)throw new Error('公开预览不连接算力卡，请使用获授权的私有入口。');const r=await fetch(path,options);let data;try{data=await r.json();}catch{throw new Error('本地服务没有返回有效响应，请重新启动 MVP 服务。');}if(!r.ok){const e=new Error(typeof data.detail==='string'?data.detail:'参数格式不正确，请检查后重试。');e.httpStatus=r.status;throw e;}return data;}
const liveJson=value=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});
function liveJobStatus(j){if(j.status==='failed')return `<div class="task-failure"><strong>生成未完成</strong><p>${esc(j.error||'执行失败，请检查素材后重试。')}</p>${B('修改后重试','reedit','small-button',`data-job="${j.id}"`)}${B('重试 · 算力卡计费','retry','small-button primary',`data-job="${j.id}"`)}</div>`;if(j.status==='cancelled')return '<div class="cancelled-task">任务已取消 · 已发生的算力费用不会退回</div>';return `<div class="task-progress real-task"><div class="progress-line"><span class="live-dot"></span><strong>${esc(j.serverStatus==='cancelling'?'正在取消…':j.serverStatus==='running'?'生成中':(j.stage||'正在上传素材').split(' · 当前步骤')[0])}</strong><span class="elapsed">已等待 <time>${formatTime(Date.now()-j.started)}</time></span>${B(j.serverStatus==='cancelling'||j.cancelRequested?'正在取消…':'取消任务','cancel','small-button',`data-job="${j.id}" ${j.serverStatus==='cancelling'||j.cancelRequested?'disabled':''}`)}</div><div class="progress-track indeterminate" aria-hidden="true"><span></span></div>${j.connection_error||j.error?`<p class="live-connection">${esc(j.connection_error||j.error)}</p>`:''}</div>`;}
function mergeLiveJob(j,r){const previous=new Map((j.outputs||[]).map(o=>[o.id,o]));Object.assign(j,{real:true,remoteId:r.id,serverStatus:r.status,status:['done','failed','cancelled'].includes(r.status)?r.status:'running',stage:r.stage,progress:null,error:r.error,connection_error:r.connection_error,started:r.started,ended:r.ended,promptId:r.prompt_id,outputs:(r.outputs||[]).map(o=>({...previous.get(o.id),...o}))});const counts={image:0,video:0};j.snapshot={...j.snapshot,type:'video',mode:'全能参考',prompt:r.prompt.replace(/(?<!@)(图片|视频)\d+/g,t=>'@'+t),negative:r.negative,liveSettings:{...r.settings},workflowId:r.workflow_id,ratio:r.settings.ratio||'原片比例',quality:r.settings.megapixels?qualityName(r.settings.megapixels):r.settings.long_side+' px',duration:'约 '+r.settings.duration+' 秒'};if(r.references)j.snapshot.refs=r.references.map(a=>({id:(a.kind==='image'?'图片':'视频')+(++counts[a.kind]),serverAssetId:a.id,kind:a.kind,name:a.name,src:a.src,available:a.available}));for(const kind of ['image','video'])refSequence[kind]=Math.max(refSequence[kind],counts[kind]);}
async function rerunLive(original,session,button){if(original.rerunning||!original.remoteId)return;original.rerunning=true;if(button)button.disabled=true;const j={id:'live-'+crypto.randomUUID(),real:true,outputs:[],snapshot:cloneDraft(original.snapshot),cost:null,started:Date.now(),status:'running',stage:'正在提交到算力卡',token:crypto.randomUUID()};session.jobs.push(j);refreshFeed();scheduleSave();try{mergeLiveJob(j,await liveApi('/api/jobs/'+original.remoteId+'/rerun',liveJson({token:j.token})));toast('已按原输入提交，仅更换随机种子');}catch(e){if(e.httpStatus){j.status='failed';j.error=e.message;j.ended=Date.now();}else{j.status='running';j.submissionUncertain=true;j.error='连接中断，正在找回这次提交，请勿重复提交。';}}finally{original.rerunning=false;if(button)button.disabled=false;refreshFeed(true);sidebar();scheduleSave();}}
async function submitLive(snapshot,session=active(),retryJob){if(session.liveSubmitting)return false;const w=liveWorkflow(session),base=snapshot||session.draft,d={...cloneDraft(base),liveSettings:{...liveSettings(base,w)},workflowId:w.id};const problem=liveProblem(d,w,true);if(problem){inlineError(problem,'refs-library');return false;}if(!d.prompt.trim()){inlineError('写下要生成或修改的画面，例如主体动作与镜头运动。','example');return false;}const missing=(d.prompt.match(/@(图片|视频|音频)\d+/g)||[]).filter(t=>!d.refs.some(r=>'@'+r.id===t));if(missing.length){inlineError(missing.join('、')+' 没有对应素材。','refs');return false;}
const j={id:'live-'+crypto.randomUUID(),real:true,outputs:[],snapshot:d,cost:null,started:Date.now(),status:'running',stage:'正在上传素材',token:crypto.randomUUID()};session.jobs.push(j);session.title=d.prompt.slice(0,28);session.liveSubmitting=true;session.draft.error=null;state.active=session.id;closePanel();render();scheduleSave();
try{const asset_ids=[];for(const [i,ref] of d.refs.entries()){if(j.cancelRequested){j.status='cancelled';j.ended=Date.now();return false;}if(ref.serverAssetId){asset_ids.push(ref.serverAssetId);continue;}j.stage=`正在上传素材 ${i+1} / ${d.refs.length}`;refreshFeed();const a=workspace.assets.find(a=>a.id===ref.assetId),blob=a?.blob||await fetch(ref.src).then(r=>{if(!r.ok)throw new Error('无法读取参考素材，请重新导入。');return r.blob();});const form=new FormData();form.append('file',blob,(ref.name||'素材').replace(/\.[^.]+$/,'')+(ref.kind==='video'?'.mp4':blob.type==='image/png'?'.png':blob.type==='image/webp'?'.webp':'.jpg'));const uploaded=await liveApi('/api/assets',{method:'POST',body:form});asset_ids.push(uploaded.id);}
if(j.cancelRequested){j.status='cancelled';j.ended=Date.now();return false;}let imageNo=0,videoNo=0;const mapping=new Map(d.refs.map(ref=>['@'+ref.id,ref.kind==='image'?'图片'+(++imageNo):'视频'+(++videoNo)]));const prompt=d.prompt.replace(/@(图片|视频|音频)\d+/g,t=>mapping.get(t)||t);j.stage='正在提交到算力卡';refreshFeed();
const response=await liveApi('/api/jobs',liveJson({workflow_id:w.id,prompt,negative:w.negative?d.negative||'':'',settings:d.liveSettings,asset_ids,token:j.token}));mergeLiveJob(j,response);if(j.cancelRequested)await cancelLive(j);
}catch(e){j.status='failed';j.error=e.message;j.ended=Date.now();if(j.stage==='正在提交到算力卡'){j.status='running';j.stage='正在确认提交状态';j.submissionUncertain=true;j.error='本地连接中断，正在找回任务，请勿重复提交。';}}
finally{session.liveSubmitting=false;refreshComposer();refreshFeed(true);sidebar();scheduleSave();}return true;}
let livePollBusy=false;
async function syncLiveJobs(){if(publicPreview||!production||livePollBusy)return;livePollBusy=true;try{const list=await liveApi('/api/jobs');let changed=false;for(const r of list){let found;for(const s of state.sessions){const j=s.jobs.find(j=>j.remoteId===r.id||j.token&&j.token===r.request_token);if(j){found={s,j};break;}}
if(!found){let s=state.sessions.findLast(s=>s.scope==='wf:'+r.workflow_id);if(!s){s={id:'s'+nextSession++,scope:'wf:'+r.workflow_id,title:r.prompt.slice(0,28),draft:{...newDraft('video'),prompt:r.prompt,liveSettings:r.settings},jobs:[]};state.sessions.push(s);}const j={id:'live-'+r.id,real:true,snapshot:{...newDraft('video'),prompt:r.prompt,negative:r.negative,workflowId:r.workflow_id,liveSettings:r.settings},outputs:[]};s.jobs.push(j);found={s,j};changed=true;}
const j=found.j,before=JSON.stringify([j.status,j.stage,j.progress,j.error,j.connection_error,j.outputs,j.ended]);mergeLiveJob(j,r);if(j.cancelRequested&&j.remoteId&&j.status==='running'&&j.serverStatus!=='cancelling'){j.cancelRequested=false;await cancelLive(j);}if(JSON.stringify([j.status,j.stage,j.progress,j.error,j.connection_error,j.outputs,j.ended])!==before)changed=true;}
for(const s of state.sessions)for(const j of s.jobs){if(j.real&&j.status==='running'&&!j.remoteId&&Date.now()-j.started>90000&&!list.some(r=>r.request_token===j.token)){j.stage='正在确认提交记录';j.error='暂未查到提交记录，请检查算力卡队列后再试，避免重复生成。';changed=true;}}if(changed){scheduleSave();sidebar();if($('#result-feed'))refreshFeed();else if(!dialog.open&&route().name==='library')render();else if(!dialog.open&&liveWorkflow()&&active().jobs.length)render();}
}catch{for(const s of state.sessions)for(const j of s.jobs)if(j.real&&j.status==='running'){j.connection_error='本地服务暂时不可达，恢复后会继续查询。';}if($('#result-feed'))refreshFeed();}finally{livePollBusy=false;}}
async function cancelLive(j){if(!j.remoteId){j.cancelRequested=true;j.stage='正在取消…';refreshFeed();scheduleSave();return;}try{mergeLiveJob(j,await liveApi('/api/jobs/'+j.remoteId+'/cancel',{method:'POST'}));j.cancelRequested=false;refreshFeed();scheduleSave();}catch(e){toast(e.message);}}
function liveJobSettings(id){const j=findJob(id)?.j,w=workflows.find(w=>w.id===j.snapshot.workflowId),v=j.snapshot.liveSettings||{};modal('本次生成参数',`<p>${esc(w?.name||j.snapshot.workflowId)}</p><dl class="parameter-summary">${w?.fields.filter(f=>!f.hidden).map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.key==='megapixels'?qualityName(v[f.key]):f.key==='ref_size'?({match:'适配画面',max:'完整参考'})[v[f.key]]:v[f.key])}</dd></div>`).join('')||''}</dl>${w?.negative?`<div class="saved-negative"><span>反向提示词</span><p>${esc(j.snapshot.negative||'未设置')}</p></div>`:''}<p class="live-task-id">任务：${esc(j.promptId||'尚未提交')}</p><div class="dialog-actions"><a class="small-button" href="/api/jobs/${j.remoteId}/workflow" download>下载工作流 JSON</a>${B('用这些参数重新编辑','reedit','button primary',`data-job="${id}"`)}</div>`,'small-dialog');}
document.addEventListener('input',e=>{if(!e.target.matches('[data-live-field]'))return;const w=liveWorkflow(),f=w.fields.find(f=>f.key===e.target.dataset.liveField),d=active().draft,v=typeof f.default==='number'?Number(e.target.value):e.target.value;if(!e.target.validity.valid||e.target.value===''){panel.querySelector('.live-form-status')?.replaceChildren(document.createTextNode('请输入允许范围内的数值。'));return;}liveSettings(d,w)[f.key]=v;if(f.key==='duration'){document.querySelector('#live-duration-value').textContent=v;e.target.style.setProperty('--range-progress',(v-f.min)/(f.max-f.min)*100+'%');}panel.querySelector('.live-form-status')?.replaceChildren();refreshComposer();scheduleSave();});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="live-reset"]')){const w=liveWorkflow();active().draft.liveSettings=Object.fromEntries(w.fields.map(f=>[f.key,f.default]));active().draft.negative='';refreshComposer();liveIntent($('[data-popup="more"]'));scheduleSave();}});

if(production&&!publicPreview){await syncLiveJobs();setInterval(syncLiveJobs,2500);}


